(window.STORIES=window.STORIES||[]).push(...[{"n": 63, "l": "الجزء 37 | الإسراء والمعراج | العوده لمكه", "u": "https://www.facebook.com/groups/710210019782034/permalink/780951986041170/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والثلاثون\n#رحلة_الإسراء_والمعراج \n#العودة_لمكة\nاتكلمنا المرة إللي فاتت عن رجوع رسول الله ﷺ  للأرض، \nوقلنا إنه هيقابل شخصية صعبة،\nلكن قبل ما نتكلم عن عن الشخصية دي محتاجين نعرف وصية الملائكة لأمة محمد ﷺ إللي هو احنا \nإبراهيم عليه السلام وصانا بسبحان الله والحمد لله ولا إله إلا الله والله أكبر،\nأما الملائكة فكان لهم وصية مختلفة، يقول رسول الله ﷺ إنه كل ما يعدي على مجموعة من الملائكة يقولوا له مُرْ أمتك بالحجامة،\nيعني يا محمد أؤمر أمتك إنهم يحتجموا، والحجامة يعني استخراج الدم الفاسد من الجسم، ولها فوائد كثيرة جدا بس مش موضوعنا هنا\nاحنا هنرجع للشخصية الصعبة المختلفة إللي رسول الله ﷺ قابلها في رحلته ،الشخصية دي كانت مِلك من الملائكة، الملك ده كان 《مَالك خازن النار》\nبعد ما رسول الله ﷺ خلص صلاة بالأنبياء رأى من حائط بيت المقدس الشرقي جهنم\nوشاف ملك من الملائكة وهو بيُقلب جمر في النار ، عارفين زي ما بنقلب الجمر أو الفحم المولع كده\nولما بنقلب الجمر بيطلع من حوله زي شرارة ، رسول الله ﷺ شاف الشرارة بتاعة الجمر وهي عاملة زي القصر الكبير،\n\"إِنَّهَا تَرْمِي بِشَرَرٍ كَالْقَصْرِ \"\nطبعا رسول الله ﷺ لم يدخلها وهي لم تؤذيه أو تمسه، هو شايفها بس\nقال جبريل عليه السلام لرسول الله ﷺ : يا محمد هذا مالك صاحب النار فسلم عليه.\nفرسول الله ﷺ الْتفت يبص عليه لقى رجل عابس\nيُعرف الغضب في وجهه، يعني واحد مكشر إللي يشوفه يعرف إنه غضبان، \nفبدأ مالك رسول الله ﷺ بالسلام وقال : السلام عليك يا محمد!\nفسلم عليه رسول الله ﷺ، \nعايزاكم تتخيلوا الموقف، واحد وشه غضبان وبيقول لك إزيك، إحساسك هيبقى عامل إزاي، لو رديتي هتردي وإنتي كشّة وخايفة... وإنتي بتبعدي، \nفإنتم تخيلوا موقف رسول الله ﷺ إللي  الملائكة كلهم كانوا بيتبسموا في وجهه ويرحبوا به وبيسلموا عليه، وده الوحيد المكشر\nحتى في بعض الروايات رسول الله ﷺ استغرب منه وسأل جبريل عليه السلام هو مضحكش في وجهي ليه،\nفجبريل عليه السلام قال لرسول الله ﷺ :\nهو لو كان بيضحك لحد كان ضحك لك، لكنه لا يضحك\nتخيلوا بقى إن ده خازن النار، الواحد منا في الدنيا لما يقابل شخص لأول مرة ويكشر في وشه حتى لو بيسلم عليه بيضايق منه إزاي\n  مالك بقى خازن النار لا يتبسم أبدا، وده يعطينا انطباع بقول الله عز وجل:\n\"عَلَيْهَا مَلَائِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ \" \nرئيس ملائكة لم يتبسم لرسول الله ﷺ،  فتخيلوا هيكون معاملته لأهل النار عاملة إزاي\nربنا يعافينا وينجينا منها برحمته \nرأى رسول الله ﷺ بعض الناس إللي بيعذبوا في النار، من المشاهد دي إنه شاف ناس بيأكلوا الجِيَف، يعني بياكلوا جثث ميتة معفنة\nتخيلوا والعياذ بالله لما الواحد بيعدي ويكون في حيوان ميت وتبقى ريحته طلعت، بنبقى مش طايقين ريحته، في ناس بقى هتاكله في النار، يعني مش بس هيبقى عذابهم النار، لأ ده كمان هياكلوا الجيف\nرسول الله ﷺ سأل جبريل عليه السلام مين الناس دي\nفجبريل عليه السلام قال له:\nهؤلاء الذين يأكلون لحوم الناس!\n《الغيبة》كبيرة من الكبائر \n☆محتاجين نقف هنا وقفة صح\nالغيبة انتشرت بطريقة صعبة مع انتشار مواقع التواصل الإجتماعي بالذات\nمتخيلين إن ممكن شخص ياخد لقطة شاشة لمنشور واحد منزله، ويقعد يشتم فيه، والناس تدخل تشتم فيه، وشوفوا كمية المشاركة والنشر والتعليقات،\nوتخيلوا إن كل دي غيبة\nالغيبة معناها ذكرك أخاك بما يكره كما قال رسول الله ﷺ،\nسواء بأخلاقه أو بلبسه أو بشكله أو أي حاجة تضايقه\nيعني تفكري كده لو أنا قلت الكلمة دي الشخص ده هيزعل ولا لأ ، أو لو عرف إني قلت عليه كده هيكره إني قلت الكلام ده ولا لأ\nتخيلوا لما واحدة تطلب نصيحة في مجموعة مثلا عالفيس، لمشكلة مع صاحبتها ولا مع زوجها، والناس تسيب المشكلة وتقعد تشتم في الزوج ولا في صاحبتها،\nمتخيلين إن كل دي غيبة\nومحدش يقول هو احنا نعرف زوجها ده شخص مجهول\nهنا مش مجهول لأن الناس حددت وقالت زوجك ده كذا، المجهول لما نيجي نقول: ده في ناس بتعمل كذا كده يبقى مجهول ومفيش غيبة\nممكن واحدة تقول طيب أنا أصلا مغلطتش ما هي كده فعلا\nرسول الله ﷺ قال :لو فيه الكلام ده يبقى اغتبته لو مش فيه الكلام يبأى بهتّه\nوالبهتان إن الإنسان يفتري على أخوه المسلم بكلام غير صحيح،\nزي ما واحد ييجي يقول ده الشيخ الفلاني ده منافق\nويصمم ويحلف، طيب إنت عرفت منين والنفاق ده أصلا حاجة في القلب محدش يقدر يعرفها غير بوحي من عند ربنا\nفتخيلوا لما تجتمع الغيبة مع البهتان ده هيبقى وضعه إيه في الآخرة\nوفي مشهد ثاني للناس إللي بيأكلوا لحوم الناس ويتكلموا في أعراضهم رآهم رسول الله ﷺ وعندهم أظافر من النحاس بيقطعوا بها وجوههم وصدورهم \nالموضوع صعب جدا ربنا يعافينا...يا جماعة حافظوا على نفسكم، أي حد يجيب سيرة الناس قصادكم نبهوه وقولوا له ياخد باله، واحنا نفسنا لازم ناخد بالنا كويس أوي من كلامنا،\nمش هنخسر حاجة لو متكلمناش،\nلكن لو اتكلمنا أكيد هنخسر كثير، رسول الله ﷺ  قال إن أكثر أهل النار هم النساء،\nوقال إن أكثر حاجة بتدخل الناس النار هو اللسان والفَرْج\nفعلى إيه المغامرة، لأ...خلينا نمسك لساننا ونبعد عن أي مواضيع فيها كلام عن الناس بصفة عامة،\nدي جنة ونار مش هزار....\nالواحد لو قعد مع إنسان مكشر طول اليوم بيبقى مش هيطق، فما بالكم بخزنة جهنم الغلاظ الشداد وعلى رأسهم مالك إللي حتى لم يتبسم في وجه رسول الله ﷺ \nخلونا مع رحمة ربنا والجنة أحسن واحنا شفنا بس وصف بسيط للجنة وكنا مبسوطين بها فما بالكم لما ندخلها\nمحدش يستاهل إننا نتعذب بسببه، نتعذب عشان شوية كلام لا هيودي ولا يجيب، لا معلش مش عايزين\nكل واحد فينا من النهاردة يتوب عن الغيبة ويستغفر، \nويدعي للناس إللي اغتابهم قبل كده، ويبدأ مع ربنا صفحة جديدة، وناخد بالنا من كلامنا بعد كده سواء لو احنا إللي بنتكلم أو الناس هي إللي بتتكلم معانا\nوخليكم فاكرين دايما إننا طول ماحنا على قيد الحياة فلسه في فرصة للتغيير للأحسن وأهم حاجة إننا لا نيأس ومهما غلطنا نتوب ونستغفر ونبدأ من جديد\nمن المشاهد إللي رسول الله ﷺ شافها في النار، إنه رأى عاقر الناقة، فاكرينه...الرجل من قوم صالح عليه السلام إللي قتل الناقة \nورأى رسول الله ﷺ ناس شفاههم بتتقص بمقصات من نار،\n\"رجالا تقرض شفاههم بمقارض....\"\nفسأل رسول الله ﷺ جبريل عليه السلام مين الناس دي\nفجبريل عليه السلام قال له:\nإن دول الخطباء من أمتك يأمرون الناس بالبر والمعروف والطاعات وناسيين نفسهم مش بيعملوا إللي بيقولوا للناس عليه\n◇ولازم هنا توضيح عشان الناس متفهمش غلط\nالمقصود من الكلام إن إللي هيتعذب العذاب ده هم الناس إللي بيقعدوا يقولوا للناس اعملوا واعملوا واعملوا وهم مش بيعملوا حاجة خالص من إللي بيقولوا عليها،\nودول عكس الناس إللي بتجاهد نفسها في عمل الطاعات ونشر الدين حتى لو كانوا مقصرين ومش بيعملوا بكل إللي بيقولوا عليه\nالأصل إن الإنسان يأمر بالمعروف ويعمله وينهى عن المنكر وميعملوش،\nلكن لو قصر في أي عمل... ده مش مبرر له إنه يترك الأمر بالمعروف ولا النهي عن المنكر،\nبالعكس ده هياخد إثمين، إثم إنه لا يعمل المعروف\nوكمان إثم ترك الأمر بالمعروف والنهي عن المنكر  \nفالمطلوب مننا إننا نجاهد نفسنا في عمل المعروف واجتناب المنكرات،\nولو وقعنا في منكر أو قصرنا في عمل معروف نستمر برده في الأمر بالمعروف والنهي عن المنكر\nمشاهد النار في حادثة الإسراء والمعراج مكنتش كثيرة لأن الغاية من الإسراء والمعراج كان إسعاد رسول الله ﷺ وإنه يرى آيات ربنا وأد إيه ربنا راضي عنه،\nفي حديث تاني رسول الله ﷺ  هيشرح مشاهد لأهل النار بس ده هيكون بعد الهجرة، \nفلما ييجي وقته هنشرحه إن شاء الله \nوكمان من الأحداث إللي حصلت إن رسول الله ﷺ اجتمع مع إبراهيم وعيسى وموسى عليهم جميعا السلام،\n وقعدوا يتكلموا عن الساعة يعني يوم القيامة ميعاده امتى، واتكلموا عن علامات الساعة،\nفإن شاء الله هقول إللي حصل بينهم لما نتكلم عن علامات الساعة الكبرى \n☆نيجي بقى للسؤال المهم إللي ملخبط ناس كثير\nهو إزاي رسول الله ﷺ شاف الناس إللي بتتعذب دي ولسه يوم القيامة مجاش\nالموضوع بكل بساطة إن ربنا جعل رسول الله ﷺ يرى مآل الناس دي\nنوضح أكثر، هو الزمن بيد مين \nالزمن بيد الله عز وجل وربنا قادر إنه يجعل رسول الله ﷺ يشوف إللي هيحصل للناس دي،\nمش احنا ساعات بنشوف رؤيا وبعدين تتحقق بعد كم سنة نقول أيوة أنا شفت الحدث ده قبل كده،\nفطبيعي جدا إن ربنا يقرب الزمان لرسول الله ﷺ ويشوف مآل الناس إللي هي لسه عايشة هيكون إيه\nوخصوصا إن دي حاجة بسيطة بالنسبة لمعراجه ﷺ للسماء ورؤية العجائب من خلق الله \n وهنلاقي حتى في القرآن ربنا بيتكلم عن أحداث يوم القيامة مثلا بصيغة الماضي في القرآن،\nفهل معنى كده إن في قيامة قامت قبل كده\nلأ... استخدام الفعل الماضي عشان يعبر عن المستقبل عشان يقول لنا الأحداث دي هتحصل أكيد بدون أي شك\nوالمشاهد إللي رسول الله ﷺ شافها كانت لناس بيعذبوا في النار،\nغير بقى الأحاديث إللي بتتكلم عن عذاب الناس في القبر دي موضوع تاني \nعشان بس نفرق بين الإثنين، لأن في ناس بتنكر عذاب القبر وبيقولوا إن الحساب هيبقى يوم القيامة فقط،\nوالكلام ده غير صحيح\n◇عالسريع كده الإنسان لما بيموت بيكون حالتين \nإما بيُنعم أو بيُعذب،\n☆إللي بينعم بيكون جاوب صح على أسئلة الملكين منكر ونكير :\nمن ربك؟ ما دينك؟ من نبيك ؟\nفبيُفتح له باب من الجنة ويكون معاه عمله الصالح على هيئة رجل طيب الرائحة جميل المنظر يُؤنسه لحد يوم القيامة، \nوروحه تُنعم في الجنة،\n ويكون لنعيم الروح أثر على الجسد، يعني الجسد كمان هيتنعم مع الروح لكن مش زي نعيم الجسد والروح في الآخرة،\n☆وإللي بيُعذب ثلاثة أنواع:\n¤نوع بيُعذب في قبره لحد ما مقدار السيئات يخلص وبعدين يُنعم في قبره لحد يوم القيامة زي ماقلنا من شوية \n¤والنوع الثاني واحد سيئاته كثيرة جدا وعذاب القبر مكفاش سيئاته، فده هيُعذب في النار لحد ما يوفي سيئاته وبعدين يدخل الجنة\n¤النوع الثالث: الكفار ودول بيتعذبوا في القبر وفي النار إلى الأبد ربنا يعافينا \n رسول الله ﷺ ركب البراق ورجع مع جبريل عليه السلام لمكة، وفي طريق العودة حصلت موقف هيكون له الأثر بعدين،\nكان في قافلة تجارية راجعة لمكة، فرآها رسول الله ﷺ وكان في بعير لهم هرب وواحد منهم راح يدور عليه ولقاه،\nوشاف على رأس القافلة يعني في مقدمة القافلة جمل لونه أسود والمتاع إللي عليه لونه إسود، \nوهو معدي على البراق سلم عليهم، فقالوا :ده صوت محمد\nالمهم وصل رسول الله ﷺ لبيته في مكة، وكل الأحداث دي كانت في ليلة واحدة،\nرجعنا لأرض الواقع مرة تانية، رجعنا لمكة ورجعنا لكفار قريش، ورجعنا للدعوة ومهمة بناء أمة الإسلام\nأنا بصراحة مش عارفة رسول الله ﷺ هيتعامل مع الناس دي تاني إزاي\nيعني الواحد كان نسي أصلا إن أبو جهل ده موجود ولا أمية بن خلف، ولا غيرهم من المشركين،\nوده واحنا بس بنسمع فما بالنا برسول الله ﷺ، أكيد هو كان نفسه يفضل في السماء في العالم المثالي ده وسط الملائكة زي ماحنا تمنينا وتشوقنا للعالم ده\nلكن رسول الله ﷺ عارف إن وراه مسؤولية ورسالة لازم يؤديها الأول، \nأكيد نظرته لكل حاجة هتتغير، نظرته للحياة الدنيا، ونظرته للناس ونظرته للإبتلاءات والأذى،\nرسول الله ﷺ حياته هتتغير تماما بعد الرحلة دي\nأتمنى إننا كمان نظرتنا للحياة الدنيا اتغيرت وعرفنا إننا هنسيبها في يوم من الأيام وإننا هنرجع لبيتنا الحقيقي في الجنة إللي بنيناه بالاثنا عشرة ركعة النوافل،\n وزرعنا حوله النخل والأشجار والزروع بسبحان الله والحمد لله ولا إله إلا الله والله أكبر، ووضعنا فيه كنوز بلا حول ولا قوة إلا بالله \nأسأل الله العظيم رب العرش العظيم أن يجمعنا جميعا أنا وكل من يقرأ كلامي في الفردوس الأعلى من الجنة بصحبة رسول الله ﷺ وصحبة إبراهيم وموسى وعيسى وجميع الأنبياء عليهم السلام\nكما جمعنا بصحبة سيرتهم في الدنيا يارب آمين\nإن شاء الله الجزء الجاي هنشوف رسول الله ﷺ بدأ يتعامل مع الناس وإيه خطته الجديدة لنشر الدعوة \n♡"}, {"n": 64, "l": "الجزء 38 | أهل مكه والإسراء", "u": "https://www.facebook.com/groups/710210019782034/permalink/783256252477410/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والثلاثون\n#أهل_مكة_والإسراء\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما رجع من رحلة المعراج، وقلنا إن الرحلة كانت في ليلة واحدة،\nرسول الله ﷺ رجع لبيته بعد الرحلة إللي شاف فيها عجائب خلق الله، أو زي ما ربنا قال:\n\"لقدْ رَأَىٰ مِنْ آيَاتِ رَبِّهِ الْكُبْرَىٰ\"\nلما جاء الصبح رسول الله ﷺ كأنه انتبه للأحداث إللي حصلت\nشوفوا لما يحصل معاكم موقف وتبقوا متفاجئين فتكونوا مستسلمين للأحداث، وبعدين لما تقعدوا مع نفسكم كده وتسترجعوا إللي حصل تتصدموا ،\nوتقولوا إزاي ده حصل\nأهه رسول الله ﷺ بشر زينا بيحس بنفس المشاعر بتاعتنا،\nلما رجع بيته وقعد يسترجع الأحداث طبعا كان في حالة ذهول، وهيقول للناس الكلام ده إزاي...هو عارف إنهم هيكذبوه\nماهو بقى عنده خبرة، بقاله معاهم عشر سنين خلاص حفظهم \n☆والخبرة مهمة جدا في الدعوة بجانب العلم\nيعني لما يكون شيخ بقاله ثلاثين أو أربعين سنة في الدعوة  واتعامل مع كل الشخصيات، خبرته هتكون مختلفة تماما عن شاب لسه بادئ في الدعوة \nلكم أن تتخيلوا كده الوضع لما رسول الله ﷺ يروح يقول لهم يا جماعة أنا روحت بيت المقدس ورجعت في ليلة واحدة وطلعت في السماء وشفت الجنة وشفت النار والملائكة و...و...\nمتخيلين رد فعل الناس هيكون إيه وهم أصلا مش مقتنعين إن الكون ده له إله واحد فقط \nكانت أم هانئ بنت أبي طالب أخت على بن أبي طالب في بيته ﷺ  فحكى لها إللي حصل ، وبعدين رسول الله ﷺ وهو خارج من البيت عشان يروح يقول للناس،\nراحت أم هانئ شدته من ثيابه لدرجة إن بطنه بانت وقالت له: \nإياك تقول حاجة للناس ، هيكذبوك وهيؤذوك\nفقال رسول الله ﷺ: والله لأحكي لهم\nماهو مش معنى إن الكلام إللي هقوله ده هيزعل الناس ومش هيقتنعوا به ويكذبوني يبقى مقلهوش\nلأ...أقوله مادام الكلام حق\nورسول الله ﷺ مصمم إنه يقوله لأنه حق ودين لازم يقوله للناس \nفخرج رسول الله ﷺ وراح قعد لوحده عند الكعبة وهو مهموم، هو عايز يقول للناس بس مش عارف يبدأ إزاي ولا يقول لهم إزاي\nشوفي لما بتبقي عايزة تفاتحي زوجك ولا والدتك في موضوع وإنتي عارفة إن هيحصل قلق من ورا الموضوع ده ومش عارفة تبدإي إزاي ولا تقولي إيه بتبقي عاملة إزاي\nشوفي مشاعرك دي كانت زي مشاعر رسول الله ﷺ تقريبا\nالمهم رسول الله ﷺ  قاعد حزين مهموم ، \nفعدى عليه مين...أبو جهل \n☆رجعنا للناس دي تاني\nفلما عدى عليه وشافه وهو مهموم كده، عرف إن في حاجة ، ماهي مش دي طبيعة رسول الله ﷺ ،\nفقرب أبو جهل لعنه الله من رسول الله ﷺ وقعد جنبه وسأله وكلامه فيه استهزاء :\nفي حاجة حصلت...هاااا في جديد\nفقال رسول الله ﷺ: نعم! ...يعني أه في جديد \nفقال أبو جهل : إيه\nقال رسول الله ﷺ :\nأنا أُسْرِي بي الليلة! يعني أنا روحت مكان امبارح بالليل،\nفقال أبو جهل : روحت فين\nفقال رسول الله ﷺ: إلى بيت المقدس!\nفقال أبو جهل: يعني إنت روحت بالليل بيت المقدس والصبح كنت معانا\nفقال رسول الله ﷺ: نعم!\nفأبو جهل لم يُظهر إنه بيكذب رسول الله ﷺ عشان يعني رسول الله ﷺ ميقولش بعدين لو نادى على أهل مكة أنا مقلتش\nفقال أبو جهل لرسول الله ﷺ بمكر وخبث : لو أنا جمعت لك الناس دي كلها هتقول لهم الكلام إللي إنت قلته لي دلوقتي ده\nفقال رسول الله ﷺ : نعم! يعني أه اقول لهم\n☆معلش بقى عشان انا بحب الحتة دي أوي\nلما حد بيكون عايز يمكر ويحارب الدين ويتعامل بخبث قال يعني عشان يقضي على الدين،\nوالمسكين مش فااااهم إنه بيواجه رب العالمين\nيعني إنت هتمكر وتحارب وهتبذل طاقتك كلها ومش بس ربنا هيذلك ويغلبك ،\nلأ ..ده هيستعملك إنت ذات نفسك في نصرة الدين إللي إنت كنت بتحاربه ده\nفاكرين أرطبون العرب عمرو بن العاص والمكر إللي مكره عشان يقضي على المسلمين النتيجة كانت إيه\nقمة الخذلان لوفد قريش وقمة النصر للمسلمين، \nفمهما حصل متقلقوش،\n ربنا بيدافع عن دينه وعن المؤمنين،\nزي بالضبط لو واحد قال أنا هغبر الدنيا بالتراب عشان أخفى ضوء الشمس،\n هيقدر؟ ..مش هيقدر ولو عمله،ا التراب مش هيستمر في الجو، وأول واحد هيغرق بالتراب هو\n\"فَلَا تَحْسَبَنَّ اللَّهَ مُخْلِفَ وَعْدِهِ رُسُلَهُ.\"\nأبو جهل دلوقتي بيخطط إنه يضحك الناس على رسول الله ﷺ ويبين إنه كاذب وخلاص جت الفرصة\nوهو مش عارف أصلا إن رسول الله ﷺ  عمال يدور على طريقة ينادي بها على الناس عشان يحكي لهم مش عارف \nفالفرصة جت : أنادي على الناس تقول لهم؟ أيوة نادي على الناس وهقول لهم،\nوينادي أبو جهل بأعلى صوته على كل مكة وأهل مكة كلهم ييجوا لأبو جهل يشوفوا هو عايز إيه،\nولو كان رسول الله ﷺ هو إللي قام ونادى عليهم مكنش حد فيهم هيلتفت له أصلا\nعايزاكم تتخيلوا ..رسول الله ﷺ قاعد عند الكعبة مرتاح متحركش من مكانه وأبو جهل هو إللي عمال ينادي وصوته اتنبح عشان يجمع الناس \n\"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ \"\nبجد آمنت بالله\nيعني الموضوع لو اتخطط له مش هتكون نتيجته كده خالص، فسبحان مدبر الأمور\nجاء الناس لأبو جهل وجنبه رسول الله ﷺ وقعدوا قصادهم،فقال أبو جهل لرسول الله ﷺ احكي للناس إللي إنت حكيته لي\nفقال رسول الله ﷺ للناس :إني أُسرِيَ بي الليلة! \nفقالوا : روحت فين\nفقال رسول الله ﷺ : إلى بيت المقدس!\nفقالوا : وبعدين الصبح كنت معانا\nقال رسول الله ﷺ: نعم!\nفاللي قعد يضرب كف على كف \n ، وإللي حط إيده على رأسه\nوإللي متعجب للكذب\n ، وإللي قعد يضحك على ما نام على ظهره من الضحك كده يعني\n \nوكل ده ورسول الله ﷺ ينظر إليهم\nتخيلوا قلبه ساعاتها كان عامل إزاي، واحد راجع من رحلة زي دي وقلبه مليان بالمشاعر إللي متتوصفش ، \nوييجي ناس زي دي ويسخروا ويكذبوا ويضحكوا عليه\n تخيلي لما تكوني بتقولي حاجة حقيقية والناس كلها تكذبك وتسخر منك كده، الموقف زي ماهو مؤلم لنا، كان مؤلم لرسول الله ﷺ \n☆ورحلة الإسراء والمعراج زي ماكانت لتسلية قلب رسول الله ﷺ، فهي كانت ابتلاء للمسلمين\nفالموقف الواحد إللي بيحصل ممكن يكون لي ابتلاء وأجر، ونفس الموقف لواحد تاني عبرة وعظة، \nيعني أنا ربنا وهبني شيء أو ابتلاني بشيء، فالابتلاء ده ربنا يرزقني به الأجر، \nولما حد يشوف عليّ الإبتلاء يتعظ ويعتبر، واحد تاني يشكر نعمة ربنا عليه، واحد ثالث يكفر بالله\nماهو يقول هو ليه ربنا يعمل كذا وكذا، ويبدأ يقيس الامور بعقله فيكفر بالله\nوهو ده إللي حصل هنا\nبعد ما رسول الله ﷺ قال للناس عن الإسراء في ناس من المسلمين ارتدوا عن الإسلام\nماهي الناس بدأت تتكلم \n شوفوا الكذب وصل لحد فين...يروح بالليل ويرجع الصبح، إنت تصدق دي، ده لو حد مجنون ميصدقش الكلام ده\nكفار قريش بقوا يبحثوا عن أصحاب رسول الله ﷺ عشان يحكوا لهم ويفتنوهم عشان يكذبوا رسول الله ﷺ، \nفقابلوا أبو بكر ..عبد الله بن أبي قحافة صاحب رسول الله ﷺ أول من آمن من الرجال الأحرار\nفقالوا له : يا أبا بكر! سمعت صاحبك بيقول إيه\nفقال لهم : وهو قال إيه\nفقالوا : بيقول إنه راح بيت المقدس ورجع في ليلة واحدة \nفقال لهم : هو قال كده فعلا\n \nفقالوا : نعم \n فقال لهم: صدق! لو كان قال كده فعلا فهو صادق\nفقالوا له: إنت مصدقه\nفقال لهم : أشهد بالله إنه لصادق\n \nفقالوا له: تصدقه إنه راح الشام ورجع في ليلة واحدة\nفقال لهم : أنا بصدقه في أبعد من هذا، أصدقه في خبر السماء يأتيه في لحظة \nالموضوع منتهي... بكل بساطة أنا آمنت بوجود الله من البداية وصدقت إن ربنا بيبعث الأنبياء والرسل وصدقت إن محمد ﷺ نبي من عند الله،\nخلاص أي تشويش ييجي بعد كده مش هبص له أصلا ولا له أي لازمة عندي\nعشان كده رسول الله ﷺ  سماه في الموقف ده الصديق\n☆وده الفرق بين المؤمن الثابت وغيره، أبو بكر ثبت قصاد الإبتلاء ده، ليقينه التام بالله وتصديقه الكامل لرسول الله ﷺ، \n أما غيره فارتد، وربنا لا يظلم أحد، لو كان في قلوب إللي ارتدوا خير مكنوش ارتدوا\nفالابتلاء لتمييز الصفوف، هل الناس هتثبت ولا هتقع\nمحتاجين نتعامل مع الدين ومع رسول الله ﷺ زي أبو بكر كده صح\nييجي لنا الحديث الصحيح خلاص.. نؤمن ونصدق ونطيع\nالدنيا قلق في مكة دلوقتي وأبو بكر بيقول إن محمد ﷺ صادق، طيب نتأكد إزاي إذا كان صادق ولا لأ\nخلاص تاهت ولقيناها\nسألوا رسول الله ﷺ: تقدر توصف لنا بيت المقدس\nهم عارفين إن رسول الله ﷺ مرحش بيت المقدس ولا مرة في حياته، \nعمره كله مقضيه في مكة، وناس كثيرة من مكة عارفين المسجد الأقصى ، فانت لو كنت روحت إوصف لنا المسجد الأقصى\nفقام رسول الله ﷺ  وقف عند الحجر، حجر إسماعيل عليه السلام، وبدأوا يسألوا رسول الله ﷺ عن تفاصيل المسجد الأقصى،\nأصلا في الطبيعي لما بنكون رايحين مكان لأول مرة مش بنركز في المكان، وخصوصا لو رايحين المكان ده واحنا دماغنا مشغولة بحاجة تانية،\nفرسول الله ﷺ راح للمسجد الاقصى في رحلة عجيبة، ودخل لقى الانبياء وأجواء إيمانية مش جاي يتفرج على تفاصيل ، وكمان بالليل \nهيفتكر إزاي\nبدأوا يسألوه..قول بقى كان في كم شباك؟\nفي كم باب ناحية اليمين؟\nكان في رسمة  على الباب ولا كان دهان؟\nوحطوا بقى كل الأسئلة إللي تتخيلوها، ماهم عايزين يعجزوه أصلا، فهتلاقي كل واحد طالع بكلمة \nالمشكلة بقى إن رسول الله ﷺ لازم يجاوب\nفقال رسول الله ﷺ إنه أصابه كرب شديد جدا ومبقاش عارف يعمل إيه\nفربنا أظهر لرسول الله ﷺ  بيت المقدس وبقى يجاوب على أسئلتهم وهو بينظر إليه وهم مش شايفينه،\nيسألوا سؤال ...رسول الله ﷺ يبص عالمسجد ويجاوبهم \nفكفار قريش قالوا: الوصف إللي إنت وصفته صحيح \nفزادهم بقى رسول الله ﷺ وقال لهم أنا عندي دليل على صدق كلامي،\nلما كنت راجع عديت على قافلة لكم، في مكان كذا وهتيجي يوم كذا وكان في بعير لهم هرب وراح جابه فلان، وعلى مقدمة القافلة في جمل أسود وعليه متاع أسود،\nفقالوا : ماشي نستنى ونشوف\nفلما جاء اليوم إللي رسول الله ﷺ قال لهم عليه، لقوا قافلة داخلة عليهم وفي مقدمتهم جمل أسود عليه متاع أسود،\nزي ما وصف رسول الله ﷺ  بالضبط،  يعني كل حاجة طلبوها منه أهه وكمان زادهم بدليل الطبيعي وإللي عنده أي ذرة عقل يؤمن،\nدول بقى ولا الهوى، قالوا احنا مش مصدقين الكلام إللي بيقوله محمد \n☆والله يا جماعة بنقابل الناس دي \nبتبقى دماغهم حاجة كده عجيبة ربنا يعافينا\nتقولك هاتيلي دليل من القرآن أو السنة على كذا وتجيبي وتقول لأ، الكلام ده مش صح\nبعد ده كله وميؤمنوش، فطبيعي إنه يحزن ﷺ \nشوفوا ربنا قال له إيه عشان يهون عليه وعلينا احنا كمان طبعا\n\" قَدْ نَعْلَمُ إِنَّهُ لَيَحْزُنُكَ الَّذِي يَقُولُونَ فَإِنَّهُمْ لا يُكَذِّبُونَكَ وَلَكِنَّ الظَّالِمِينَ بِآيَاتِ اللَّهِ يَجْحَدُونَ \"\nيعني هم مش بيكذبوك هم مصدقينك لكن دي ناس جاحدة، عرفوا الحق وجحدوه\nمش يسكتوا بقى ، لأ ده قعدوا يتكلموا في الموضوع ده أيام كثيرة، \nكان المسلمون بيقعدوا مع رسول الله ﷺ  كل يوم بيسألوه عن الحاجات إللي شافها وكان بيشرح لهم، \nفكانوا عايشين جو إيماني جميل ، زي إللي عشنا زيه في الأجزاء إللي فاتت \nبس تخيلوا بقى لما يكون رسول الله ﷺ إللي بيحكي،\nنحس إن الجنة نزلت للأرض\n◇عندنا سؤال مهم\nهو ليه رسول الله ﷺ أخبر المشركين عن رحلته لبيت المقدس ولم يخبرهم عن رحلة المعراج للسماء\nبكل بساطة عشان يقدر يجيب دليل على إنه راح بيت المقدس، يعني وصف لهم المسجد الأقصى وقال لهم على القافلة، وكمان كذبوه\nلكن هيجيب دليل إزاي إنه طلع السماء\nدول كفار هيكذبوه، لكن المسلمين المؤمنين بمجرد ما هيقول لهم عن المعراج هيؤمنوا على طول\nوالإسلام لا يشوش على العقول، يعني حدثوا الناس بما يعرفون وحدثوا الناس بما يعقلون،\nمينفعش نقعد نكلم الناس كلام هم مش فاهمينه وعقولهم مش مستوعبه، كده نفتنهم\nوطبعا ده لا يتعارض مع إللي قلناه من شوية إننا لازم نقول الحق،\nاحنا نقول الحق إللي نقدر نثبته، رسول الله ﷺ قال الحق إللي يقدر يثبته بالدليل،\nوفاكرين في قصة يوسف عليه السلام لما دخل معاه الفتيان وطلبوا تفسير الرؤيا ، \nقبل ما يتكلم جاب لهم دليل على صدق الكلام إللي هيقوله فأثبت لهم بالدليل إنه بيفهم في تأويل الرؤى، قال لهم:\n\"قَالَ لا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِ إِلا نَبَّأْتُكُمَا بِتَأْوِيلِهِ قَبْلَ أَنْ يَأْتِيَكُمَا\"\n  فعروج رسول الله ﷺ  للسماء محتاج إيمان بالغيب، والكفار معندهمش إيمان بالغيب، دي بتاعة المسلمين الموحدين \nفده يعلمنا إننا لما نيجي نكلم الناس في مسألة شرعية يبقى معانا أدلتها وقناعتها وإيماننا بها والإثبات إنها حق\nهيرجع رسول الله ﷺ للدعوة مرة ثانية، وهتاخد الدعوة منحنى مختلف، لأن الوضع في مكة دلوقتي بعد كل ده لا يبشر إن مكة هتكون مركز لإنطلاق الإسلام للعالم\nعمل إيه رسول الله ﷺ عشان يتجه بدعوة الإسلام لمنحنى جديد ، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 65, "l": "الجزء 39 | عرض الإسلام علي القبائل", "u": "https://www.facebook.com/groups/710210019782034/permalink/783276105808758/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والثلاثون\n#عرض_الإسلام_على_القبائل\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما حكى لأهل مكة إللي حصل له في الإسراء، وشفنا إزاي بعد ما رسول الله ﷺ جاب لهم الدليل على صدق كلامه كذبوه برده\nوكده بقى واضح جدا إن رسول الله ﷺ  محتاج ناس تانية، خلاص الناس دي مبقتش نافعة،\n رسول الله ﷺ حاول معاهم عشر سنين ومفيش فايدة \nأول محاولة لرسول الله في إنه يبحث عن ناس تانية تشيل هم الإسلام وتدافع عنه كانت في الطائف واحنا شفنا النتيجة كانت إيه\nرسول الله ﷺ بدأ يبحث في الحج عن القبائل القوية ويعرض عليهم الإسلام، هو كان بيعرض الإسلام على القبائل في الحج السنين إللي فاتت دي لكن المرة دي الوضع مختلف،\nلأنه مش بس هيطلب منهم إنهم يُسلموا، ده كان بيطلب منهم مع الإسلام إنهم ينصروه\n☆موقف رسول الله ﷺ  ده بيعلمنا نقطتين:\n♡أولا :\nإننا لا نيأس ولانستسلم، \nفهو بعد ما حصل إللي حصله في الطائف مقلش خلاص مفيش نتيجة، لأ..ده قعد يدور على ناس غيرهم\n♡ثانيا : \nإننا نُتبع السبب\nفاكرييين قصة ذو القرنين لما ربنا قال عنه : فَأَتْبَعَ سَبَبًا \nيعني كان بيشوف الحاجة المتاحة ويشتغل فيها،  بيشوف الباب إللي ربنا فتحه قصاده ويستغله\nأهه رسول الله ﷺ إللي نزل عليه قصة ذو القرنين استفاد من تجربة ذو القرنين لأنه عارف إن ربنا مش بيقص عليه قصص السابقين كده وخلاص ، ده في عبرة منها\nفرسول الله ﷺ شاف دلوقتي إن قريش بقت باب مسدود مفيش فيه أمل،\nموقفش بقى وصمم على قريش وقعد يقول أنا كده حياتي هتقف، ومش هينفع أدعو ناس تانية مادام أنا معرفتش أدعو أهل مكة و...و...\nبكل بساطة رسول الله ﷺ ساب الباب المقفول ده وبدأ يدور على أبواب ثانية،\nفَأَتْبَع إيه\n..فَأَتْبَعَ سَبَبا\nفنتعلم من رسول الله ﷺ  وذو القرنين إننا نستغل الأبواب المفتوحة،\nمثلا ربنا فتح لك باب دراسة علوم شرعية من عالنت وسماع المحاضرات ،\nبس إنتي عايزة تنزلي تروحي المسجد تحضري فيه، وموضوع المسجد مش متاح دلوقتي،\nتوقفي حياتك بقى ولا تستغلي الباب المفتوح\nفهو ده إللي رسول الله ﷺ  عمله، لقى باب قريش مقفول بعد محاولات كثيرة، جاء الوقت إللي ندور فيه على باب ثاني\nاحنا دلوقتي في نهاية السنة العاشرة من البعثة،\nبدأ رسول الله ﷺ يزور الوفود إللي بتيجي للحج، ويعرض عليهم الإسلام وإنهم ينصروه ويدافعوا عنه عشان يبلغ دعوة الإسلام،\nراح لبني كلب وبني كِندة وبني حنيفة وغيرهم من القبائل وكان بيقول لهم، إنه رسول من عند الله يأمركم بعبادته وترك عبادة الأصنام،\nوكلهم كانوا بيرفضوا، ماعدا قبيلة واحدة بس هي إللي أخذت الموضوع بجدية\nقبيلة بني عامر، قبيلة قوية جدا ومن أعز قبائل العرب، فهم من الخمس القبائل إللي محصلش في تاريخها سبي لنسائها،\nيعني محدش قدر يغلبها في تاريخها،\nتخيلوا بقى لما قبيلة بالقوة دي تاخد الإسلام على محمل الجد، الإسلام ممكن ينتشر بسرعة أد إيه ومحدش يقدر يمس رسول الله ﷺ  بسوء\nعرض رسول الله ﷺ الإسلام على قائدهم وكان اسمه بَيْحَرة بن فِراس،\nفاهتم جدا بالإسلام ووقف وسط أصحابه يقول لهم قصاد رسول الله ﷺ : أنا لو أخذت الفتى ده من قريش هاكل به العرب\nيعني هو عرف إن كلام رسول الله ﷺ حق وعرف إن إللي هيمشي وراه هيسود العرب ويملكهم كلهم\nفعرض على رسول الله ﷺ عرض مغري جدا\nقال لرسول الله ﷺ :\nهل لو احنا بايعناك وبعدين ربنا أظهرك ونصرك على من خالفك، يكون لنا الملك من بعدك؟\nيعني بيقول لرسول الله ﷺ احنا هندخل الإسلام وندافع عنك ضد أي حد يخالفك، وهنساعدك إنك تكون زعيم ، وهتفضل إنت القائد والزعيم كده لحد ما تموت،\nلكن بعد موتك الزعامة تنتقل لنا احنا\nعايزاكم تتخيلوا العرض المغري ده وموقف رسول الله ﷺ\nرسول الله ﷺ الدعوة قصاده في مكة مقفولة، أهل مكة بيحاربوا دعوته،\nمحدش من القبائل راضي يؤمن به ولا يساعده، هو نفسه في حماية رجل كافر المطعم بن عدي،\nوممكن يترك حماية رسول الله ﷺ لو قريش ضغطوا عليه،\nالمسلمين نصفهم في الحبشة والباقي بيتعذب في مكة،\nفالعرض ده يعتبر عرض مثالي جداا وفي وقت قاتل،\nواحنا أصلا مصدقنا لقينا حد يوافق على الإسلام\nوفي مقابل إيه، مقابل إنه يكونوا هم الزعماء بعد رسول الله ﷺ، يعني يعتبر حاجة بسيطة\nيعني رسول الله ﷺ هو الحاكم وهيتبعوا كل أوامره،\nرسول الله ﷺ رد على الكلام ده بإيه\nقال رسول الله ﷺ: الأمر لله يضعه حيث يشاء!\nيعني يا بيحرة، لو إنت هتستحق إنك تقود المسلمين من بعدي وعندك القدرات إللي تأهلك لكده،\nربنا هيخليك إنت إللي تحكم، لكن لو غيرك هو إللي يستحق فربنا هيعطي الولاية للي يستحقها\nيعني من الآخر رسول الله ﷺ رفض الشرط بتاع بيحرة\nفقال له بيحرة : يعني احنا نعرض نفسنا للقتل وبعدين لما ربنا ينصرك يكون الملك لغيرنا\nلا معلش مش عايزين\n◇طبعا كلنا مستغربين رد فعل رسول الله ﷺ، يعني هو كان ممكن يقبل بشرطه ده، وبعدين لما الرجل يُسلم يبقى يقنعه ويفهمه عادي مع الوقت وهيستجيب أكيد\nده تفكير الناس إللي بتبص تحت رجلها مش للمستقبل، رسول الله ﷺ قدوة  الناس إللي هتيجي بعده هيعملوا زيه،\nهو كان ممكن يعرض المال على الناس عشان يتألف قلوبهم،\nويدخلوا الإسلام،\nلكن الزعامة وحكم المسلمين مينفعش\nليه بقى\n، لأن لما الزعيم بيكون ضال وهمه الدنيا، ضلاله مش بيؤثر عليه لوحده، ده هيؤثر على كل الامة\nلأن الشخص الحريص على الزعامة هتلاقيه بيعمل كل المحرمات عشان يحافظ على زعامته وملكه\nقتل عادي...تعذيب ميضرش...سجن وضرائب و..و..\nوالزعيم إللي يعيش لدنيته هيهمل دين الناس، وأي قرار غلط هيعمله الناس كلها هتمشي وراه،\nفأهم حاجة بالنسبة لزعماء الدنيا إنهم يحافظوا على زعامتهم وملكهم بأي طريقة، ومش مهم بقى إيه إللي يحصل بعد موتهم\nلكن رسول الله ﷺ مش من زعماء الدنيا، رسول الله خايف على الناس في زمنه وفي كل زمن هييجي بعد موته ﷺ، \nفإزاي يستأمن على المسلمين واحد زي بيحرة كل همه الزعامة وحب السيطرة، وهو ده هدفه من دخوله في الإسلام\nيعني هو مش داخل الإسلام عشان بيحبه وعايز ينصره، هو كان عايز يدخل الإسلام لأن هو عارف إن الإسلام هيحكم الناس فهو عايز يكون الحاكم\nوالناس إللي همها الدنيا ودايما تفكر أنا نصيبي فين، أو انا هستفاد إيه، لا ينصروا الإسلام أبدا،\nلكن إللي ينصر الإسلام هو إللي بينسى نفسه وهو بيخدم الإسلام وعينه على الآخرة\nوبكده تكون المفاوضات فشلت مع بني عامر ورجعنا لنقطة الصفر تاني\nعلى الرغم من إن رسول الله ﷺ شغال في الدعوة وبيبذل مجهود عشان ينشر الإسلام، إلا إنه لم يُهمل حياته الشخصية،\nفي السنة العاشرة من البعثة دي،\n جاءت لرسول الله ﷺ خولة بنت حكيم زوجة عبد الله بن مظعون تشجعه على الزواج،\nفقال لها مين بعد خديجة، فقالت له : عائشة بنت أبي بكر صاحبك، فقال لها صغيرة، وكانت عائشة في الوقت ده عمرها ست سنين،\nفقالت له الصغيرة تكبر، فقال لها طيب ومن لبناتي لحد ما تكبر، فقالت له سَوْدَة بنت زَمعة،\nزوجها مات وسابها بين أهله المشركين، فرضي رسول الله ﷺ  وتزوجها شفقة بها لأنها كانت مسنة، ومكنتش ذات جمال،\nوعقد على عائشة بنت أبي بكر رضي الله عنها وهي بنت ست سنوات ودخل بها وهي عندها تسع سنوات زي ما هنشوف بعدين\n☆طبعا لازم نقف هنا ونوضح موضوع زواج رسول الله ﷺ  بعائشة وإنه إزاي يتزوج طفلة، وإيه الحكمة من زواجه منها على رغم فرق السن إللي بينهم واشمعنى رسول الله ﷺ  تزوج عائشة وهي صغيرة ،\nورفض إنه يزوج ابنته فاطمة من أبي بكر أو عمر بحجة إنها صغيرة وزوجها لعلي بن أبي طالب\nناخدهم واحدة واحدة \n◇أولا : \nهو لم يتزوج طفلة لم تبلغ ،رسول الله ﷺ  عقد على عائشة وهي بنت ست سنين ولم يدخل بها إلا بعد البلوغ وهي عندها تسع سنين،\nومفيش واحدة تبص لبنتها إللي عندها تسع سنين وتقول إزاي رسول الله تزوج بنت صغيرة كده\nالسيدة عائشة كانت طويلة، وكمان كانت عايشة في مكة وهي بلد حار والبلاد الحارة يكون فيها البلوغ أسرع،\nفلما نقول إن السيدة عائشة كان عمرها تسع سنين وهي طويلة يعني هي في جسم بنت عندها ستة عشرة سنة من بناتنا دلوقتي\nفهي كانت تصلح للزواج ورسول الله ﷺ مش هيتزوج امرأة لا تصلح للزواج\n◇ثانيا: \nمن حكمة ربنا إن رسول الله ﷺ  يتزوج عائشة على الرغم من فرق السن إن عائشة كان واضح عليها علامات الذكاء والفطنة والفصاحة والفهم،\nفرسول الله ﷺ شاف إنها هتكون أقدر من غيرها على نقل أقواله وأحواله للناس،\nفحياته ﷺ لازم تكون معروفة لنا عشان نتبعه، فلازم إللي ينقل عنه وينقل أحواله يكون ذكي وعنده حكمة\nوكمان هي ابنة أحب الناس إليه أبو بكر الصديق،\nفدي تعتبر كرامة لأبي بكر الصديق رضى الله عنه\nو بالمناسبة كل النساء إللي هيتزوجهم مش عشان شهوة زي ما الناس بتطعن فيه ﷺ،\nوإلا كان تزوج وهو صغير في شبابه، وكمان مكنش أول واحدة يتزوجها بعد خديجة متكونش جميلة،\nلو هو هيتزوج عشان شهوة الزواج كان اختار أجمل النساء\nلكن كل زواجاته كانت لهدف وهو إن الناس تقلده في التعامل مع زوجاته\nفهو تزوج البكر والثيب والكبيرة والصغيرة، فكل واحدة في نسائه كانت نموذج مختلف وهو اتعامل معهن جميعا \n◇ثالثا: \nالأصل إن المرأة تتزوج القريب منها في السن، عشان يكون في تكافؤ ويكون في ألفة بين الزوجين،\nعشان كده رفض إن فاطمة تتزوج من أبي بكر أو عمر،\nلكن لو في مصلحة أكبر ممكن نتجاوز الشرط ده،\nوطبعا المصلحة في زواج رسول الله ﷺ من السيدة عائشة كبيرة جدا،\nده غير إن رسول الله ﷺ رأى رؤيا مرتين إنه يتزوج عائشة رضي الله عنها، ورؤيا الأنبياء حق\nخلصت السنة العاشرة من البعثة، ودخلنا في السنة الحادية عشرة، استمر رسول الله ﷺ في الدعوة أسلم بعض الناس مش مشهورة أسمائهم لأنهم ماتوا بعد إسلامهم بشهور قليلة،\nوكان رسول الله ﷺ لسه في حماية المطعم بن عدي،\nقعد السنة دي كلها يدعو الناس ويعلم الدين للمسلمين، \nويشرح لهم الآيات،\nويقرأ القرآن على أهل مكة بس مفيش فايدة فيهم برده،\nوكانوا بيقعدوا يجادلوا رسول الله ﷺ ومن أمثلة الجدال بتاعتهم،\nإن العاص بن وائل وهو سيد من سادات مكة جاء لرسول الله ﷺ وكان في إيده عظم بالي قديم وراح مفتته قصاد رسول  الله ﷺ وبقى تراب وقال له : بقى ربنا هيُحيي التراب ده بعد ما اتفتت كده\nفقال له رسول الله ﷺ:\nأيوة هيبعثه.. ثم يميتك ثم يحييك ثم يُدخلك نار جهنم\nفنزلت فيه :\n\"أَوَلَمْ يَرَ الْإِنسَانُ أَنَّا خَلَقْنَاهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ *\nوَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ ۖ قَالَ مَن يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ*\nقُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ\"\nاستمر الوضع كده خلال السنة الحادية عشرة لحد ما جاء موسم الحج،\nوبدأ رسول الله ﷺ يعرض نفسه على القبائل مرة ثانية،\nلكن المرة دي رسول الله ﷺ غير من خطته،\nيعني هو كان بيروح يعرض نفسه على القبائل في النهار وكان أبو لهب يشوفه ويكذبه، أبو جهل يعطل عليه ويسخر منه\nالمهم يعني إن الدعوة كانت بتوصل للناس مشوشة وفيها قلق،\nلكن السنة دي رسول الله ﷺ عمل خطة جديدة،\nلأن المطالب السنة دي أقوى، رسول الله ﷺ هيطلب من الناس الإسلام وكمان الدفاع عنه وعن المؤمنين ومواجهة قريش،\nوقريش لو عرفت المطالب دي هتبقى مشكلة جامدة\nفاحنا محتاجين سرية تامة\nوالسرية دي أنسب وقت لها في الليل، ولأن رسول الله ﷺ  ميعرفش القبائل القوية من الضعيفة ولا تاريخ زعماء القبائل ولا أنسابهم،\nفهو محتاج لواحد خبير في الأنساب، يبقى مفيش أحسن من أبي بكر الصديق خبير الأنساب \nفبدأ رسول الله ﷺ  يزور القبائل في مخيماتهم خارج مكة في الليل،\nوكده ضربنا عصفورين بحجر، الدعوة هتوصل للناس بدون تشويش وعلى روقان، \nولو في قبيلة وافقت إنها تنصر رسول الله ﷺ محدش من أهل مكة هيعرف هي مين\nرسول الله ﷺ مع إنه مُؤيد من ربنا لكن بيعلمنا الأخذ بالأسباب وإننا نخطط عشان مهمتنا تنجح\nكان رسول الله ﷺ بيقابل القبائل فلما أبو بكر الصديق رضي الله عنه يقول له إن القبيلة دي ضعيفة كان يعرض عليهم الإسلام من غير ما يطلب منهم نُصرة،\nولو القبيلة قوية بيعرض عليهم الإسلام ويطلب منهم النصرة،\nذهب رسول الله ﷺ لقبائل كثيرة ومحدش منهم استجاب لرسول الله ﷺ،  محدش آمن\n☆وهنا نتعلم نقطة مهمة وهي إن احنا علينا البلاغ فقط\nيعني يا جماعة احنا علينا توصيل الدين مش إننا نلزم الناس بيه\nيعني لما تقولي لواحدة إن النمص حرام مثلا وهي لا تستجيب خلاص إنتي عملتي إللي عليكي، إنتي ملكيش إنك تلزميها ولا تغصبي عليها،\nمن الأمور إللي بتخلي الناس تنفر إنهم يحسوا إننا بنلزمهم وإنهم لازم يسمعوا كلامنا،\nاحنا بنعرض عليهم الدين، والله قبلوا فلله الحمد مقبلوش خلاص مش بإيدنا إننا نلزمهم، \n\"فَإِنْ أَعْرَضُوا فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا\"\nالمشكلة بقى إننا لما منلاقيش الناس استجابت لنا نتعصب ونتضايق وممكن نتهم الناس بكلام مش ظريف\nلا يا جماعة رسول الله ﷺ وهو رسول الله مألزمش أي حد بالدين، هو كان بيبلغ وخلاص، وهي دي وظيفته ووظيفتنا من بعده\n\"إِنْ عَلَيْكَ إِلَّا الْبَلَاغُ\"\nمن القبائل إللي رسول الله ﷺ دعاهم كانت قبيلة بني شيبان، كان أبو بكر الصديق رضي الله عنه بيسأل : مَن القوم فيردوا ويقولوا بني فلان،\nفلما سأل القبيلة وقالوا له إنهم بني شيبان بن ثعلبة، قال أبو بكر لرسول الله ﷺ : \nيارسول الله بأبي انت وأمي، الناس دي من أعظم القبائل قبيلة كبيرة وعزيزة \nولما سأل عن أساميهم لقى أشراف بني شيبان موجودين : مفروق بن عامر وهانئ بن قُبيصة والنّعمان بن شُرَيك  والمثنى بن حارثة\nهيبدأ الحوار وأبو بكر الصديق رضي الله عنه هيسأل بني شيبان،\nهيسألهم عن إيه؟\nوهل هيؤمنوا ولا هيكونوا زي غيرهم من القبائل؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 66, "l": "الجزء 40 | وفد الخزرج انشقاق القمر", "u": "https://www.facebook.com/groups/710210019782034/permalink/783286765807692/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الأربعون\n#وفد_الخزرج\n#انشقاق_القمر\nوقفنا المرة إللي فاتت عند بني شيبان القبيلة القوية إللي رسول الله ﷺ  هيعرض عليهم الإسلام،\nوكان أشراف بني شيبان موجودين وهم :\nمفروق بن عامر وهانئ بن قُبيصة والنّعمان بن شُرَيك  والمُثنى بن حارثة،\nبدأ معاهم الكلام أبو بكر الصديق بكلام يثيرهم عشان يشوف حماسهم وقوتهم إيه،\nيعني بالبلدي كده يشوف ميتهم إيه\nفسألهم أبو بكر:\n إنتم عددكم أد إيه؟\nفقال له مفروق: احنا أكثر من ألف والألف محدش يغلبهم بسبب قلتهم\nفأثاره أبو بكر وقال له:طيب وإيه أخبار المَنعة فيكم\nيعني تقدروا تحموا إللي يستجير بكم ولا إيه\nفمفروق حس بالإهانة إزاي أبو بكر ينتقص منهم وإنهم مش أقوياء،\nفرفع صوته وقال لأبي بكر: \nاحنا لما بنواجه حد بتكون دي أشد الأوقات غضب، \nواحنا بنفضل وبنحب الخيل ورعايتها على حبنا لعيالنا،\nوالنصر من عند الله ينصرنا مرة وينصر الناس علينا مرة \n☆متنسوش إن العرب كانت تؤمن بوجود الله خالق للكون، لكنهم كانوا بيشركوا معه آلهة تانية في العبادة\nهو ده الكلام إللي أبو بكر الصديق رضي الله عنه كان عايز يسمعه من مفروق، عشان لما يطلب منه الوقوف أمام قريش ميرجعش في كلامه وميكنش متردد،\nمفروق كان واخد باله من أسئلة أبي بكر الصديق رضي الله عنه وعرف أنه عايز حاجة معينة،\nرسول الله ﷺ مكنش لسه دعاهم لحاجة ، أبو الصديق هو إللي بيتكلم بس،\nفقال مفروق لأبي بكر : لعلك أخو قريش؟\nيعني هو إنت الرجل إللي ظهر في قريش وبيدعو لدين جديد\n \nفرد عليه أبو بكر بذكاء عايز يكسب نقطة في صالحه قال له:\nإيه ده هو وصل لكم إنه رسول الله\nيعني كأنهم متفقين دلوقتي إن محمد رسول الله وخلاص اعترافهم بإنه رسول أمر واقع\nلكن مفروق كان ذكي برده وخد باله من سؤال أبي بكر فقال له: وصل لنا إنه بيتقال كده\nفالتفت مفروق لرسول الله ﷺ وسأله وإنت بتدعو لإيه بقى يا أخا قريش\nفبدأ رسول الله ﷺ يتكلم قال :\nأدعو إلى شهادة أن لا إله إلا الله وحده لا شريك له وأني رسول الله ، وأدعوكم إنكم تؤوُوني وتنصروني،\n لأن قريش كذبت برسالتي وتكبرت على أمر الله واتبعوا الباطل وتركوا الحق\nمفروق عجبه كلام رسول الله ﷺ وهو مكنش خايف من قريش لكنه حب يتعرف على الدين أكثر،\nفسأله عن الدين إللي بيدعو له، فرسول الله ﷺ فكر إنه يقرأ عليه القرآن،\nلكن رسول الله ﷺ هيختار الآيات المناسبة للموقف،\nمش هيروح يحكي لهم مثلا قصة نوح وهلاكهم،\nالموقف مش مناسب خالص\nلكن نظر في الوفد لقاهم ناس على مستوى عالي من الأخلاق فشاف آيات القرآن إللي بتدعوا للأخلاق الحميدة،\nيعني كأن رسول الله ﷺ بيدور على أرض مشتركة يقف معاهم فيها\nودي من حكمته ﷺ إللي لازم نتعلمها، لما نيجي ندعي حد نشوف شخصية إللي قصادنا دي مهتم بإيه أو الصفات إللي فيه وأبدأ أدخل له من الناحية دي وبعدين أقول إللي أنا عايزاه بعد كده\nرسول الله ﷺ قرأ عليهم آيات من سورة الأنعام نشوف مع بعض :\n\"قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا بِهِ شَيْئًا ۖ وَبِالْوَالِدَيْنِ إِحْسَانًا ۖ وَلَا تَقْتُلُوا أَوْلَادَكُم مِّنْ إِمْلَاقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ \nوَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَعْقِلُونَ\"\nانبهر مفروق بكلام القرآن ومعانيه وإعجازه والأخلاق إللي بيدعوا لها، لدرجة إنه قال لرسول الله ﷺ: بتدعو لإيه يا أخا قريش؟\nيعني عايز يسمع كلام تاني من القرآن \nفرسول الله ﷺ قرأ عليه برده آيات عن الأخلاق قال:\n\"إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَىٰ وَيَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ وَالْبَغْيِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ \"\nفتأثر مفروق بكلام القرآن وقال لرسول الله ﷺ:\nإنت دعيت لمكارم الأخلاق ومحاسن الأعمال، فعجبه الإسلام \nوقعد يشتم في قريش \nلكن مفروق ميقدرش ياخد قرار لوحده هو أه زعيم وشريف في قومه بس في ناس معاه لازم يستشيرهم،\nفحب إنه يعرف رأي أصحابه فقال لرسول الله ﷺ وهو بيشاور على صاحبه :\nده هانئ بن قبيصة شيخنا وصاحب ديننا\n يعني عنده خلفية دينية وأنا حابب آخذ رأيه، فالظاهر إن هانئ كان معجب بالإسلام ومكنش معترض عليه،\nلكنه كان خايف ياخد قرار يورط بني شيبان في حرب مش بس مع قريش ..لأ ده مع العرب كلهم\nفقال هانئ لرسول الله ﷺ:\nأنا سمعت كلامك يا أخا قريش، لكن مش منطقي خالص إننا نترك ديننا ونتبعك من قعدة واحدة كده، \nيعني إنت كلامك حلو وكل حاجة بس عايزنا من قعدة واحدة ومن كم كلمة قلتها نشقلب حياتنا كلها ونحارب الدنيا ... مستحيل\n☆وعلى فكرة ده منطق ناس كثير من المسلمين للأسف\nلما نيجي نكلمهم عن اتباع الدين وربنا قال ولازم تعملوا، \nيقولوا يعني إنتم عايزينا نغير حياتنا فجأة كده ونشقلبها مرة واحدة، ماحنا طول عمرنا عايشين كده ومبسوطين \nمعندهمش أي استعداد للتنازل عن أي حاجة لله\nالمهم هانئ قال لرسول الله ﷺ : انت ترجع واحنا نرجع ونفكر وبعدين يحلها ربنا،\nفكأن هانئ بينسحب انسحاب مؤدب يعني\nيبقى مفروق موافق، هانئ متردد ويميل لعدم الموافقة دلوقتي،\nوبما إن الموضوع في حرب يبقى محتاجين نستشير وزير الحربية بتاعنا، فقال هانئ لرسول الله ﷺ وهو بيشاور على صاحبهم الثالث:\nده المُثنى بن حارثة شيخنا وصاحب حربنا\nيعني هو المسؤول عن الحرب ونحب نسمع رأيه،\nوالمثنى صاحب عقلية عسكرية وفارس شجاع ومشهور وسط العرب،\nفقال المثنى : أنا سمعت كلامك يا اخا قريش، ورأيي من رأي هانئ\nيعني أنا مش حابب إننا نتسرع في الدخول للإسلام، لكن المثنى أضاف نقطة جديدة عن الوضع العسكري لبني شيبان وهو ده إللي هيحسم الموضوع بأه أو لأ،\nقال المثنى لرسول الله ﷺ:\nقبيلتنا بين مائين، ماء العرب وأنهار كسرى \n☆قبيلة بني شيبان كانت قريبة من نهر الفرات في العراق على الحدود يعني وكانت العراق تحت ملك كسرى ملك الفرس.\nفاحنا هنقدر نساعدك وننصرك على قبائل العرب،\nلكن نعدي لمياه كسرى ونروح نقاتلهم معلش مش هنقدر على ده، احنا أه ألف ونقدر نتغلب على العرب،\nلكن الفرس جيشهم أكثر من اثنين مليون جندي\nهنحاربهم ولا نقف قصادهم إزاي دول\nده غير كده احنا بيننا وبين كسرى عهد، وهو إننا لا نُحدث حدثا ولا نُؤوي مُحدثا،\n يعني كسرى واخد مننا عهد إننا لا نخترع حاجة جديدة ولا ندافع عن أحد جاء بحاجة جديدة، \nوأنا شايف إن إنت والدين بتاعك ده من الحاجات إللي الملوك بتكرهها\nفلو انت عايز ،احنا نقدر نؤويك وننصرك على العرب بس\nطبعا ده تقدم رهيب جدا وفرصة ذهبية لرسول الله ﷺ\nيعني هو أصلا مطارد من العرب دلوقتي، \nفخلاص نخلص العرب وبعدين لما ييجي وقت فارس يبقى يحلها ربنا وأهه الإيمان يكون اتمكن من قلوب الناس دي وهيفدوا الدين بأرواحهم\nلكن رسول الله ﷺ رفض عرض المثنى\nقال له: \nكويس أوي إنكم قلتم إمكانيتكم بكل وضوح، بدل ما تتفقوا معايا وبعدين تخلفوا كلامكم،\nوبعدين قال له قاعدة أساسية مهمة جدا عن الإسلام لازم نعرفها احنا كمان:\n《دين الله عز وجل لن ينصره إلا من أحاط به من جميع جوانبه》\nيعني مش ممكن إللي ينصر الإسلام يقعد يختار أنا هاخد ده وأسيب ده، مش طماطم هي\nالإسلام يعني الإستسلام لكل أوامر ربنا، مش هاخد من الأوامر إللي يوافق هوايا وظروفي وإللي مينفعش معايا أسيبه، \nالعبودية لله إننا ننفذ كل أوامر ربنا زي ما قالها لنا ونترك إللي نهانا عنه\nفرسول الله ﷺ رفض العرض بتاعهم لأنه عايز ناس وقت ما يقول لهم ربنا قال كذا ينفذوا فورا من غير ما يقعدوا يقولوا ليه وعشان إيه والحكمة من كده إيه ،\n طيب أفهم الأول ماهو احنا عقولنا دي مش زينة يعني وربنا مدينا عقل نفكر بيه ...إلخ من الكلام إللي يشل\n◇مش معنى كلامي إننا نلغي العقل عشان بس الناس إللي مبتصدق\nننفذ أوامر ربنا وبعدين ممكن نفكر في الحكمة بعدين، مش إننا نعرض أوامر ربنا ونواهيه على عقولنا وإللي يمشي معاه يبقى حلو نعمله وإللي مش فاهمينه نعترض عليه ونقول لأ مش هنعمله\nالمهم رسول الله ﷺ قبل ما يمشي إداهم مفاجأة كده\nقال لهم: \nأمة فارس إللي إنتم خايفين منها دي لو ربنا أورث المسلمين أرضهم وأخذوا نساءهم سبايا ساعتها تسلموا؟\nفقالوا له : طبعا نسلم\nيعني بيقول لهم هتشوفوا إن أمة فارس دي إللي جيشها أكثر من اثنين مليون المسلمين هيتغلبوا عليهم ويهزموهم\nطبعا احنا الموضوع بالنسبة لنا حاسينه عادي لأن احنا عارفين إن الإسلام انتشر وفعلا المسلمين فتحوا بلاد فارس،\nلكن الناس دي مكنوش لسه عارفين حاجة،\nتخيلوا واحد من مجاهل أفريقيا جاي يقول لمجموع من الأمريكيين الكفار مثلا يا جماعة احنا هنؤذن في البيت الأبيض وهيكون ده مقر خلافة المسلمين\nهيكون رد فعلهم إيه \nأهه ده كان تقريبا وضع رسول الله ﷺ في الوقت ده،  تحت حماية رجل كافر ، المسلمين مضطهدين ومُفرقين،\nإزاي بقى ناس بالمنظر ده هيهزموا أقوى دولة في العالم إللي جيشها بس مش الشعب يزيد على اثنين مليون جندي\nفشلت المفاوضات مع بني شيبان، ورسول الله ﷺ  لم ييأس، هو عنده خطوط واضحة وقواعد أساسية مش هيتنازل عن أي حاجة منها،\nولحد دلوقتي لقينا ناس وافقت على المبدأ بس كانوا أصحاب دنيا،\nولقينا ناس تانية وافقوا نص نص، يبقى أكييييد هيلاقي إللي بيدور عليهم بس أهم حاجة إنه يستمر في البحث ولا ييأس،\nلأن الإنسان بيفشل لما يتوقف عن المحاولة،\nلكن طول ماهو بيحاول يعمل إللي هو عايزه هيوصل أكيد وهيحقق إللي كان نفسه فيه\nانتقل رسول الله ﷺ لوفد تاني كان مكون من ستة رجال،\nسألهم إنتم منين؟\nفقالوا احنا مجموعة من الخَزْرَج، فسألهم رسول الله ﷺ:\nأه...إنتم من حلفاء اليهود؟!\nفقالوا له: أيوة من حلفاء اليهود\nفقال لهم :طيب ممكن نقعد نتكلم مع بعض شوية ؟!\nقالوا له : أه عادي \nفعمل معاهم رسول الله ﷺ زي باقي القبائل دعاهم للإسلام وقرأ عليهم القرآن،\nفآمن الستة كلهم مرة واحدة في نفس اللحظة\n☆إيه ده مين الناس دي إللي آمنوا كلهم بدون أي تردد كده\nالخَزْرج دول قبيلة مشهورة في يثرب، وفي قبيلة تانية معاهم في نفس البلد اسمهم الأوس، \nوكان بيسكن معاهم اليهود وكانوا حلفاء للأوس والخزرج ويثرب بعيد عن مكة حوالي خمسمائة كيلو متر،\nوده يوضح لنا أد إيه رسول الله ﷺ كان مُطلع على أحوال زمانه وعنده معلومات عن القبائل بصفة عامة،\nاليهود إللي كانوا عايشين في يثرب مع الأَوْس والخَزْرج، كانوا كل ما يحصل خلاف بينهم يقولوا للأوس والخزرج :\nالزمن ده زمن نبي وأول ما يظهر هنتبعه ونقتلكم قتل عاد \nفمن كثرة ما اليهود بيقولوا كده الأوس والخزرج كرهوا اليهود، وفي نفس الوقت كانوا خايفين منهم ومع اتحادهم مع النبي إللي يظهر ده،\nالفكرة إنهم كانوا مصدقين أصلا إن في حاجة اسمها نبي،\nغير أهل مكة إللي كانوا رافضين الفكرة\nفلما سمعوا كلام رسول الله ﷺ قالوا لبعض قصاد رسول الله ﷺ:\nالحقوا \n ده إللي اليهود بيهددوكم به ، اوعوا يسبقوكم إليه\nفكان ده سبب رئيسي في إسلامهم، سبب ثاني في سرعة إسلام الوفد الخزرجي إن قبل كم شهر كان في حرب أهلية قبلية بين الأوس وبين الخزرج،\nولسه من كم شهر بس كان في حرب بينهم وكانوا هيفنوا بعض،\nفوفد الخزرج فكروا إن رسول الله ﷺ  بكلامه المعجز وأسلوبه في التعامل يقدر يجمع بين القبيلتين،\nفقالوا لرسول الله ﷺ: \nاحنا تركنا قومنا وبينهم من الشر إللي بينهم ، فيمكن ربنا يجعلك سبب في الجمع بينهم\nقالوا لرسول الله ﷺ: احنا هنرجع لقومنا وندعوهم ونعرض عليهم إللي احنا آمنا به، فلو قبلوا فمحدش هيكون أعز علينا منك\nوالستة إللي آمنوا من الخزرج دول كانوا :\n《أسعد بن زُرَارة وجابر بن عبد الله، وقطبة بن عامر وعوف بن الحارث ورافع بن مالك وعقبة بن عامر》\nورجع الستة فعلا ليثرب وبدأوا يدعوا قبيلتهم الخزرج ومش بس كده ده دعوا كمان الأوس للدخول في الإسلام ونسيوا الحرب إللي كانت بينهم ،ودخل في الإسلام اثنين من الأوس:\nالهيثم بن التيّهان وعُويْم بن ساعدة، بمعلومات بسيطة جدا عرفوها عن الإسلام انطلقوا يدعوا الناس باللي هم عارفينه،\nرسول الله ﷺ مكنش مخطط للقاء الستة دول،\nولا كان متوقع أنه هيقابلهم ، لكن لما الإنسان بيسعى ربنا بيكافؤه ويرتب له الأسباب إللي تخليه يوصل لهدفه\nعشان كده احنا علينا السعي وإننا نعمل إللي نقدر عليه والنتائج بتاعة ربنا \nاستمر الستة يدعون في قومهم سنة كاملة،\n لحد ما رجعوا في العام التالي إللي هو العام الثاني عشر للبعثة في موسم الحج عشان يقابلوا رسول الله ﷺ بعشرة من الخزرج واثنين من الأوس،\nهنعرف أحداث المقابلة إن شاء الله بس قبل كده محتاجين نعرف الحادثة العجيبة إللي حصلت قبل السنة الثالثة عشرة للبعثة \nالمشركين كانوا عايزين معجزة من رسول الله ﷺ عشان يثبت لهم إنه رسول من عند الله، \n☆قال يعني بعد ده كله ورسول الله مجبش معجزات\nبس هم كده أهل الباطل يقعدوا يجادلوا ويطلبوا أمور تعجيزية عشان يحاربوا الدين\nفقالوا لرسول الله ﷺ احنا عايزين نشوف معجزة،\nإنت مجبتش ولا معجزة،\nرسول الله مقعدش يجادلهم ويقولهم مانا قلتلكم حادثة الإسراء وجبتلكم الدليل،\nوقلت لكم على حادثة الصحيفة إللي أكلتها دودة الأرض و..و..\nهو مقعدش يعدد لهم ، قال لهم لو أنا خليت القمر ينشق نصفين تؤمنوا؟\nوكان الليلة دي القمر بدر، فقالوا له: أه طبعا نؤمن\nفدعا ربنا إنه يشق له القمر فانشق القمر نصفين \nوكان جبل أبي قبيس بينهم\nفلما شافوا المنظر قالوا : سحرنا محمد\nوكذبوا بالمعجزة إللي شافوها قصاد عينهم، فقال واحد فيهم طيب لو هو سحرنا فأكيد مش هيقدر يسحر إللي برة مكة،\nخلونا نسأل الناس إللي جايين من السفر عن إيه أكثر حاجة عجيبة شوفتوها في سفركم ده،\nفلما جاء الناس من السفر سألوهم قالوا لهم : في ليلة شفنا فيها القمر مقسوم نصين\nفراح أهل مكة قالوا : ده سحره وصل لخارج مكة ، وسحر الناس\n☆طبعا لا تعليق\nربنا انزل : \n\"اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ * وَإِنْ يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ * وَكَذَّبُوا وَاتَّبَعُوا أَهْوَاءَهُمْ وَكُلُّ أَمْرٍ مُسْتَقِرٌّ\"\nوأكيد السؤال إللي بيفرض نفسه هنا \nهو ليه ربنا لم يُهلك أهل مكة بعد ما طلبوا معجزة ولم يؤمنوا بها زي ما أهلك الأمم السابقة، \nوخصوصا إن احنا قلنا قبل كده إن جبريل عليه السلام جاء قبل كده لما طلبوا إن مكة يبقى فيها أنهار ويحولها لأرض خضراء،\n وكانوا طلبوا برده إنه يحول لهم جبل الصفا لذهب،\nفقال جبريل لرسول الله ﷺ إن ربنا بيقول لو أعطاهم إللي طلبوه وكذبوا هيهلك مكة،\nإيه الفرق بقى في الموقفين\nسؤال مهم جدا عشان كده هنجاوب عليه المرة الجاية إن شاء الله \n☆"}, {"n": 67, "l": "الجزء 41 | بيعة العقبه الأولى", "u": "https://www.facebook.com/groups/710210019782034/permalink/783297809139921/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الواحدة_والأربعون\n#بيعة_العقبة_الأولى\nاتكلمنا المرة إللي فاتت عن معجزة انشقاق القمر، ووقفنا عند سؤال مهم وهو:\n ليه ربنا لم يُهلك أهل مكة بعد ما طلبوا معجزة ولم يؤمنوا بها زي ما أهلك الأمم السابقة، \nوخصوصا إن احنا قلنا قبل كده إن جبريل عليه السلام جاء قبل كده لما طلبوا إن مكة يبقى فيها أنهار ويحولها لأرض خضراء، وكانوا طلبوا برده إنه يحول لهم جبل الصفا لذهب،\nفقال جبريل لرسول الله ﷺ إن ربنا بيقول لو أعطاهم إللي طلبوه وكذبوا هيهلك مكة،\nإيه الفرق بقى في الموقفين\nربنا بيهلك الأمم إللي بتطلب معجزة بعينها، يعني هم بيقولوا عايزين معجزة كذا،\nزي ثمود قوم صالح هم إللي طلبوا الناقة بكل مواصفتها وربنا خلقها لهم بالمواصفات إللي طلبوها،\nومع ذلك كفروا فاستحقوا العذاب والهلاك،\nولما طلب كفار مكة من رسول الله ﷺ  أنه يفَجّر لهم من الأرض ينابيع ماء، وطلبوا معجزات بعينها زي ما قلنا في الجزء الثامن عشر،\nربنا قال إنه ممكن يحقق لهم كل إللي طلبوه لكن لو كذبوا بعد كده هيهلكوا جميعا\nلكن في معجزة شق القمر هم مقلوش احنا عايزينك تشق لنا القمر،\nده رسول الله ﷺ هو إللي عرض عليهم لما قالوا له أَرِنا معجزة،\nعرض عليهم إيه رأيكم لو شققت لكم القمر تؤمنوا؟\nفقالوا له : ماشي،\nده غير كده مش كل الناس شافت انشقاق القمر،\nوالمعجزة لازم الناس كلها تشوفها زي ناقة صالح،\n  فبعض أهل مكة شافوه وبعضهم كان في بيته وإللي كان مشغول لأن القمر بيطلع في الليل والليل الناس فيه بتنام وبتقعد في بيوتها،\nمش زي عصرنا دلوقتي، يعني الدنيا بالليل كانت بتبقى ظلام مفيش أي ضوء،\nفكان النقاش مع رسول الله ﷺ في بداية الليل فأراهم آية انشقاق القمر يعني الموضوع مكنش مترتب له أصلا\nوده يوضح لنا نقطة مهمة، وهي إن ناس قليلة كملن من خارج مكة شافت انشقاق القمر،\nيعني في ناس بتُنكر انشقاق القمر بحجة إن محدش شافه من الأمم المعاصرة لأهل مكة والبشر كلهم بيشتركوا في ضوء القمر، وحاجة زي كده هنلاقي الناس بينقلوها،\n¤يبقى إزاي حصل \nبكل بساطة لأن وقت الليل الناس نايمة وحتى لو حد صاحي فهيبقى مشغول بحاجات تلهيه،\nالناس مش هتبقى قاعدة رافعة رأسها للسماء باصة للقمر ومستنيينه يتشق يعني \nوكمان لما يكون بداية الليل في مكة بيقابله في نصف الكرة الأرضية الناحية الثانية نهار،\nأو مثلا فرق توقيت، في مكة بداية ليل وفي بلاد ثانية يبقى منتصف الليل، فالكل هيبقى نايم،\nوكمان انشقاق القمر كان للحظات يعني مقعدش ليلة كاملة مُنشق، فطبيعي إن محدش ياخد باله، \nيعني احنا في زماننا كان بيحصل خسوف للقمر ومحدش بيبقى عارف ولا يشوفه إلا لو الناس قالت قبلها،\nلكن غير كده محدش بيحس بحاجة\nومتنسوش إن الخمر كان منتشر جدا في الزمن ده، فممكن لو ناس شافته تفكر إن ده بسبب الخمر فأكيد هيكذبوا نفسهم قبل ما يقولوا أي كلمة أصلا\nأما إللي قالوا إن القمر لم ينشق أصلا ولسه هينشق يوم القيامة فكلامهم شاذ لا يُعترف به لأنه مخالف للأدلة الصحيحة\nنرجع لرسول الله ﷺ في السنة الثانية عشرة للبعثة، كان رسول الله ﷺ بيدعو الناس بس كالعادة مفيش استجابة وحرب الدعوة شغالة،\nكان بيشرح للمسلمين آيات القرآن وبيعلمهم الدين لحد ما جاء وفد من المدينة في موسم الحج من السنة الثانية عشرة من البعثة،\nوكان الوفد مكون من اثنا عشر رجل من الأوس والخزرج ،\nجاءوا عشان يقابلوا رسول الله ﷺ،\nقعدوا مع رسول الله ﷺ في مكان اسمه العَقَبة، وبدأ رسول الله ﷺ يطلب منهم أمور محددة،\nقواعد الإسلام الأساسية خلونا نشوفها ونشوف هل احنا مطبقينها في حياتنا ولا لأ\n◇أولا :\nألا يشركوا بالله شيئا : تطبيق العقيدة الصحيحة، عبادة ربنا عبادة صحيحة، محدش يقدم أي أمر على أمر الله عز وجل\n◇ثانيا:\nلا يسرقوا ولا يزنوا ولا يقتلوا أولادهم ولا يأتوا ببهتان يفتروه بين أيديهم ولا أرجلهم،\nوالبهتان يعني أي حاجة بتخلي الشخص مندهش من الكذب إللي سمعه، مثال عشان المعنى يوضح\nمن أنواع البهتان: \nالغيبة والنميمة وقذف المحصنات وقول الزور وشهادة الزور والزنا، وإن المرأة تزني وتلحق ولد الزنا بزوجها،\nيعني أي حاجة مستبعشة تدخل في البهتان\nبعد العقيدة الصحيحة تيجي الأخلاق، \nمفيش قيام لأي أمة بدون الأخلاق، لو مفيش أخلاق ،ضاعت السياسة والحكم والقضاء والمعاملات\n☆وأظن إنتم شايفين واقعنا عامل إزاي، عندنا أزمة في الأخلاق رهيبة\nحتى بين إللي مفروض ملتزمين، ألفاظ صعبة ولعن بحجة الغيرة على الدين،\nورسول الله ﷺ هو أغير الناس على الدين ومع ذلك مشتمش حد أبدا على رغم الأذى إللي اتعرض له،\n وربنا أمرنا نتبعه، رسول الله ﷺ كان ممكن يدعو على المشركين زي ما شفنا لكنه أبدا مشتمهمش،\n بالعكس لما كان حد بيشتم قصاده انتصارا للدين برده كان إما بيسيبه ويمشي أو يُسكته،\nاحنا بنقعد نجاهد نفسنا عشان الصلاة والقيام والذكر و...و...عشان نبلغ درجات عالية في الجنة،\nطيب ماهو الرجل يبلغ بحسن خلقه درجة الصائم القائم،\nوفي نفس الوقت لو الصائم القائم أخلاقه سيئة هتضيع حسناته إللي تعب في تجميعها\nكل واحد فينا لازم يحسن أخلاقه حتى لو كل إللي حواليه أخلاقهم سيئة،\nحتى لو إللي حواليه ألفاظهم سيئة احنا منعملش زيهم، حتى لو استفزونا برده نخلي قدوتنا رسول الله ﷺ، \nمش احنا بنتعلم السيرة عشان نعمل زيه\nعارفين القطار السريع \nمهما كان القطار سرعته كبيرة جدا عمره ما خرج عن القطبان\nوكذلك مشاعرنا لازم نتحكم فيها مهما غضبنا، أو الناس أذتنا أو استفزتنا مينفعش مشاعرنا تخرج برة قضبان الشرع\n¤هقول لكم مثال ، أكيد كلنا عارفين حادثة قتل المسلمين في #نيوزيلاندا\nطبعا كلنا غضبانين ومتضايقين ومحروق دمنا، طيب المشاعر دي نوجهها إزاي\nهل نقعد نشتم في الرجل وفي دول الغرب وخلاص، ولا يطلع شباب يقولوا هو قَتل مسلمين آمنين، \nخلاص احنا كمان هنروح نقتل نصارى آمنين في كنائسهم أو في بيوتهم وننتقم منهم\nهل الإسلام قال كده؟\nرسول الله ﷺ لما اتغدر بسبعين واحد من أصحابه كلهم من القراء يعني بيقرأوا القرآن وبيدرسوه ليل نهار، \nحزن عليهم رسول الله ﷺ حزن شديد جدا ، مش بس لأنهم قتلوا ده كان في نفس الشهر عشرة من أصحابه قتلوا غدر برده يعني ثمانين واحد من أصحابه ، وهنعرف القصة بالتفصيل لما ييجي وقتها إن شاء الله ،\nالشاهد إن رسول الله ﷺ كان بيدعو عليهم وبيعلم المسلمين الدين ،\nلأن هو ده إللي كان يملكه ساعتها مكنش يقدر يخرج بجيش يقاتل الكفار دول لأن المسلمين كانوا لسه في مرحلة ضعف\n وفي نفس الوقت مقعدش يشتمهم، ودول كانوا كفار فما بالكم بالناس إللي بتشتم مسلمين ظاهرهم الإسلام\nلأ وشوفوا كمان رسول الله ﷺ  عمل إيه \nواحد من المسلمين كان معدي في المكان لقى السبعين رجل من الصحابة دول قُتلوا،\nفقابل بعدها وهو راجع للمدينة رجلين من نفس القبيلة إللي غدرت بالمسلمين دول وكان معاهم عهد من رسول الله ﷺ  والصحابي ده ميعرفش،\nفراح قاتلهم انتقاما للسبعين صحابي ورجع لرسول الله ﷺ، \nتخيلوا إن رسول الله ﷺ أرسل دِية الرجلين دول لأهلهم لأنهم قُتلوا خطأ\nمقلش مثلا خلاص هم اتقتلوا غلط وأصلا الناس دي قتلوا سبعين من أصحابي، فهم عليهم لي فلوس او أحسن يستاهلوا خليهم يذوقوا إللي عملوه فينا\nمهما اتعامل الناس بأخلاقهم فاحنا لينا أخلاق الإسلام بتحكمنا،\nإللي زعلان على قتل المسلمين يصلح نفسه وينصر دينه باتباع شرع ربنا\nمينفعش نتعامل مع الناس بمعاملتهم السيئة سواء مسلمين أو كفار، الشرع هو إللي بيحدد لنا طريقة التعامل مع الناس من خلال منهج رسول الله ﷺ \n◇وهو ده إللي رسول الله ﷺ طلبه من وفد الأوس والخزرج في الشرط الثالث قال:\nلا تعصوني في معروف \nأمر واضح من رسول الله ﷺ إنهم يطيعوه ولا يعصوه مادام يأمرهم بمعروف، يطيعوه في أوامره وفي نواهيه،\nيعني لما رسول الله ﷺ يقول :\n\"ليس المؤمن بالطّعان ولا اللّعان ولا الفاحش ولا البذيء\"\nيبقى على طول كلامنا ميكنش فيه أي طعن ولا لعن ولا فُحش ولا ألفاظ بذيئة حتى لو كل الناس بيقولوها\n☆وممكن حد يستغرب هو ليه رسول الله ﷺ قال لهم يطيعوه في المعروف، ماهو طبيعي إن رسول الله ﷺ مش هيقول إلا المعروف\nرسول الله ﷺ بيضع قواعد للمستقبل، قواعد لبناء الأمة في أي زمن، يعني أي حد هييجي بعدي تطيعوه لما يأمركم بالمعروف تطيعوه أمركم بمعصية لا تطيعوه،\n《لا طاعة لمخلوق في معصية الخالق》\nبعد ما رسول الله ﷺ قال لهم الشروط أو القواعد بتاعته قال لهم:\nلو عملتم إللي قلت لكم عليه ده ...جزاؤكم الجنة\nمفيش مُلك في الدنيا مفيش لكم أي حاجة في الدنيا،\nجزاؤكم في الآخرة فقط\nولو حد فيكم خالف كلامي وربنا عجّل عقوبته في الدنيا يبقى خلاص دي كفارة،\nلو ربنا ستره بعد عصيانه لكلامي فأمره لله إن شاء عاقبه وإن شاء غفر له\nكان إيه رد فعل الوفد\nوافق الوفد وبايعوا رسول الله ﷺ  على الكلام إللي قاله لهم كله، وبقى اسمها بيعة العقبة الأولى أو بيعة النساء،\nهي البيعة مكنش فيها نساء، لكن اتسمت كده لأن النساء كانوا بيبايعوا رسول الله ﷺ على الشروط دي من غير الجهاد في سبيل الله\n☆طيب وليه رسول الله ﷺ مطلبش منهم النصرة أو إنهم يجاهدوا في سبيل الله\nلأن رسول الله ﷺ عارف إن القرار مش بأيدي الناس دي، هم مجموعة من يثرب مش من الناس إللي بإيدها تاخد القرار،\nفهو مش هيحملهم ما لا يطيقوا،\nفهو الأول بيربيهم إيمانيا عشان يقدروا يدعوا قومهم ويكون عدد المسلمين أكثر وساعتها يقدروا يتحملوا مسؤولية نصرة الإسلام والدفاع عن رسول الله ﷺ \n¤طيب إزاي رسول الله ﷺ هيربي المسلمين ويدعي الناس في يثرب وهو في مكة\nكده يبقى احنا محتاجين شخص يقوم بمهمة الدعوة إلى الله  في يثرب ويكون سفير للإسلام هناك، يعلم المسلمين ويكون صورة متحركة للإسلام وقدوة للناس،\nويمهد أهل البلد نفسيا لاستقبال المسلمين من مكة أو الحبشة أو أي مكان في الأرض،\nوطبعا يدرس الوضع الاقتصادي والعسكري والأمني في يثرب عشان رسول الله ﷺ هيروح يقعد فيها،\nفمحتاجين ندرس كل حاجة ونعالجها ، احنا بنبني دولة دلوقتي فمفيش أي مجال للخطأ\nمين بقى أكثر واحد ملائم للمهمة دي...مفيش غير مصعب بن عُمير\nفاكرين مصعب وإللي أمه عملته معاه لما أسلم وكان إزاي هو أكثر شباب مكة ترفا ومع ذلك ساب كل حاجة من أجل الإسلام\nطيب ليه رسول الله ﷺ اختار مصعب بالذات ، أكيد في أسباب،\nاحنا اتعودنا من رسول الله ﷺ  إنه مش بيعمل حاجة ولا ياخد قرار إلا وله حكمة في قراره وله بُعد نظر\nخلونا نشوف الأسباب إللي خلت رسول الله ﷺ يختار مصعب بن عمير بالذات دونا عن أي واحد تاني من الصحابة \n♡أولا:\nمصعب من أوائل الناس إللي أسلمت وبالتالي هو من أعلم الصحابة وكان بيحفظ كل ما ينزل من القرآن، \nوعارف إمتى نزلت الآيات ومعناها يعني خاض التجربة الإسلامية من البداية\nوطبعا لازم يكون على علم واسع، لأن مش هينفع لما تحصل حاجة يروح يسأل رسول الله ﷺ  لأن هيكون بينه وبين رسول الله ﷺ مسافة خمسمائة كيلو،\n يعني حوالي خمس ساعات بالعربية لو ماشي على سرعة مائة كيلو متر\nفهناك مكنش فيه عربيات فتخيلوا الوقت إللي هيحتاجه عشان يوصل لرسول الله ﷺ \n♡ثانيا: \nكان من صفة مصعب رضي الله عنه إنه هادئ وصبور وعنده لباقة في الكلام وذكي وعنده سعة صدر وحليم وده صفات أساسية لازم تكون في الداعية، وكمان مصعب كان إنسان رقيق ومتواضع، يعني داعية مثالي\n♡ثالثا: \nمصعب من أشراف مكة فلما يروح لهم واحد شريف في النسب أكيد هيسمع له أشراف أهل يثرب ،بعكس لو راح لهم عبد ضعيف أو إنسان مجهول\n♡رابعا:\nمصعب كان من أغنياء مكة المشهورين، وترك الغنى والأموال عشان الإسلام،\n فهيكون قدوة لأغنياء يثرب إللي عايزين يدخلوا في الإسلام وبيترددوا بسبب أموالهم او ملكهم،\nفهو مثال عملي لرجل استطاع إنه يسيب المال من أجل الإسلام\nوكمان دليل واقعي إن دين الإسلام مش دين ثورة من الفقراء على الأغنياء ، ولا هو ظهر بسبب عوامل اقتصادية زي ما في ناس بتقول \n♡خامسا:\nالسفير المنعزل عن مكة وعايش في أمان ممكن يُفتن بالدنيا والعيشة المريحة بعد ما كان شُعلة في الدعوة،\nلكن مصعب نجح في اختبار أصعب، وهو إنه كان عايش أصلا وسط العيشة المريحة دي،\nوإللي يخليه يرفض الدنيا من يد أمه إللي كانت موفرة له كل سُبل الراحة أكيد هيرفضها من يد أي حد تاني\nونقطة تانية مهمة إن السفير الإسلامي ممكن يُفتن بفتنة الزعامة والرئاسة وإن الناس بتمشي وراه،\nلكن مصعب كان وضعه مختلف لأنه كان هيبقى زعيم في قبيلته بني عبد الدار إللي معاهم مفتاح الكعبة وبيتوارثوه،\nفكان المفتاح هيبقى في إيده ويكون هو الزعيم لولا دخوله في الإسلام\n♡سادسا:\nمصعب بن عمير كان من المهاجرين للحبشة في الهجرة الأولى والثانية، فأكيد هجرته خلته يكتسب خبرة في التعامل مع الأغراب ومع عادات وتقاليد مختلفة،\nفاللي يخليه يقدر يتعامل مع ناس غير عرب ولغتهم ودينهم مختلف عنه،\nيخليه يقدر تعامل مع عرب زيه، يعني التعامل هيكون أسهل\n♡سابعا:\nهجرة مصعب للحبشة خلت عنده القدرة إنه يسيب بلده وأحبابه، واحنا مش عارفين مهمته في يثرب هتقعد كم سنة،\nفمادام هو صبر السنين دي في الحبشة يبقى يقدر يصبر زيهم في مكان تاني\n♡ثامنا:\nمصعب كان عمره في الوقت ده خمسة وثلاثين عام، وده سن مناسب جدا للعمل في الدعوة،\nيعني لا هو شاب في بداية سن الشباب فيتهور في أخذ القرار بسبب حماسه،\nولا هو شيخ كبير في السن صعب يتحرك وتكون مهمة الدعوة شاقة عليه\nكانوا بيحفظونا واحنا صغيرين إن أول سفير في الإسلام هو مصعب بن عمير،\nلكن محدش كان بيقول لنا هو ليه كان هو السفير، مكنش حد بيقول لنا إن رسول الله ﷺ  كان بيخطط وبيختار الناس المناسبة لكل حدث،\nوإنه كان بيختار الأشخاص بعناية، ومش بيختار اختيار عشوائي كده وخلاص، \nدولة الإسلام والصحابة متبنوش في لحظة، رسول الله ﷺ  مكنش معاه عصا موسى بيحقق بها المعجزات\nرسول الله ﷺ كان بيفكر ويخطط ويأخذ بالأسباب وكان بيتعب وبيتأذى في سبيل الله،\nأي حد يقدر يعمل إللي رسول الله ﷺ  عمله ويبني دولة ويربي ناس زي الصحابة،\nوإللي يمشي على نفس منهج رسول الله ﷺ ومنهج الصحابة هيوصل أكييييد للي هم وصلوا له،\nغير كده يبقى بنضيع وقتنا وبنضيع نفسنا ربنا قال:\n\"وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ \"\nهو طريق واحد مستقيم... طريق رسول الله وصحابته،\nأي حد هياخد طريق مختصر هيضيع ويضل\nرجع مصعب بن عمير مع وفد الأوس والخزرج ليثرب عشان يبتدي مهمته،\nوهناك حصلت أحداث هتغير مجرى الدعوة الإسلامية للأبد\nمين إللي دخل في الإسلام وأدخل معه قبيلته كلها في يوم واحد\nهنعرف إن شاء الله الجزء الجاي"}, {"n": 68, "l": "الجزء 42 | انتشار الإسلام في يثرب", "u": "https://www.facebook.com/groups/710210019782034/permalink/783305939139108/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والأربعون\n#انتشار_الإسلام_في_يثرب\n كنا واقفين المرة إللي فاتت عند مصعب بن عمير لما سافر ليثرب مع وفد الإثنا عشر من الأوس والخزرج عشان يدعوا الناس إللي في يثرب ويعلم المسلمين الدين،\nهنسيب رسول الله ﷺ في مكة يكمل تعليم المسلمين ويكمل مشواره في الدعوة هناك وهنروح مع مصعب رضي الله عنه ليثرب،\nوصل مصعب ليثرب ونزل في ضيافة الصحابي أسعد زرارة إللي كان من الستة إللي أسلموا أول مرة\n وكان جاء مع الوفد إللي بايع بيعة العقبة الأولى\nدلوقتي مصعب عايز يبدأ في الدعوة، لكن هيبدأ إزاي محتاجين خطة\nفاستغل مصعب ميزة أسعد بن زرارة وهي إنه يعرف أهل يثرب كلهم ومشهور بينهم وكان حكيم جدا، مع إنه عمره مكنش لسه وصل للثلاثين، \nومش بس يعرفهم، ده له علاقات كويسة بناس كثير منهم،\nيبقى الخطة دلوقتي إن أسعد بن زرارة يأخذ مصعب بن عمير معاه ويروح يزور الناس ويعمل جولة في يثرب ويقول للناس اسمعوا من مصعب،\nيقوم مصعب يدعي الناس للإسلام ويقرأ عليهم القرآن،\nوبكده كل واحد قدر يخدم الدين بالميزة بتاعته،\nلو كان أسعد معندهوش لباقة مصعب ولا قدرته على توصيل المعلومة لكنه عنده مميزات تانية قدر يستغلها في نشر الدين\n☆الإسلام بيستغل كل الطاقات، مفيش حد ملوش لازمة في الإسلام، كل واحد عنده ميزة يستغلها وكل واحد يكمل التاني، \nوهنشوف إن شاء الله التنوع الرهيب إللي كان في الصحابة،\nهنشوف إللي كان متميز في تعلم اللغات وهنشوف إللي كان  متميز في قراءة القرآن، وإللي كان متميز في العبادة وإللي كان متميز في التخطيط للحروب،\nكل دي طاقات مطلوبة لخدمة الإسلام\nعارفين بقى احنا مشكلتنا إيه\nإن احنا عايزين نعمل الحاجة إللي عاجبانا حتى لو كانت صعبة ومش بتاعتنا وواقفين قصادها وهي متقفلة\nاحنا بنبقى عايزين نعملها عشان الموضوع على مزاجنا، \nلكن هي مش بتاعتنا، \nاحنا متميزين في حاجات تانية لو ركزنا فيها هنبدع بس احنا نكتشف ميزتنا في إيه، قدراتنا إيه،\nهل أنا قدراتي إني أكون داعية زي مصعب بن عمير، ولا قدراتي إني أجيب الناس للداعية زي أسعد بن زرارة،\nنصيحة من شخص مجرب، ركزوا على مميزاتكم وقدراتكم وإللي تقدروا عليه هتشوفوا العجب من نفسكم\nوهي دي نفس فكرة فأتبع سببا\nبدأ مصعب رضي الله عنه يدعو الناس عن طريق أسعد بن زُرارة الخَزْرجي،\nذهب أسعد لحديقة للأوس وجمع فيها لمصعب أكبر عدد يقدر يجمعه عشان يدعوهم ويقرأ عليهم القرآن،\nكان موجود في الحديقة دي سيدين من سادات الأوس قاعدين مع بعض وحواليهم بعض أصحابهم،\n《أُسَيْد بن حُضَيْر》 ،《سعد بن معاذ》 \nسعد بن معاذ كان ابن خالة أسعد بن زرارة فلما لقاه جاي ومعاه مصعب الرجل الغريب ده غضب جدا وكان لسه هيقوم يتخانق معاه لكن مسك نفسه عشان صلة القرابة إللي بينهم وقال لأُسيد بن حُضير صاحبه :\nاذهب للأثنين دول إللي جايين يقعدوا في مجالسنا وهددهم وابعدهم عن مجالسنا وقول لهم ميقربوش من الأماكن بتاعتنا، \nولولا إن أسعد بن خالتي أنا كنت روحت بنفسي وخلصت الموضوع\nفراح أسيد بن حضير ناحية أسعد ومصعب فلما شافه أسعد جاي من بعيد قال لمصعب: \nشوف الرجل إللي جاي من بعيد ده ، هذا سيد قومه فاصدق الله فيه\nفقال مصعب : لو قعد هكلمه وأدعوه\n☆أسعد بيقول لمصعب خليك صادق مع ربنا وإنت بتدعيه، خلي نيتك لله،\nوده يعلمنا إن الصدق مع الله في دعوة الناس بيفتح لنا قلوب الناس\nالعجيب بقى إن أسعد إللي لسه مسلم مبقالوش سنة بيقول لمصعب بن عمير اصدق الله فيه...خلي نيتك لله متخيلين \nمصعب القارئ العالم بالقرآن المبتلى في الله إللي عاش اثنا عشر سنة صادق مع الله أسعد بيقول له اصدق مع الله\nوالأعجب منه رد مصعب: قال له لو قعد هكلمه\nلو حد في واقعنا كان قال لأسعد إنت يابني بتقولي أنا أصدق مع الله\n إنت مش عارف أنا ابتليت أد إيه في الله\nوقعد يجيب له تاريخه الطويل في الصبر والصدق، وتضيع قضية دعوة الرجل إللي جاي ده\nبكل بساطة أسعد قال له أصدق مع الله فمصعب أخذ الكلمة وتذكر وصدق مع الله وخلصت الحكاية من غير كلام كثير ملوش لازمة\nوده التطبيق العملي لقول الله:\n\"وَذَكِّرْ فَإِنَّ الذِّكْرَىٰ تَنفَعُ الْمُؤْمِنِينَ \" \nأسعد بن زرارة رضي الله عنه ذكّر مصعب فكان مصعب من المؤمنين فنفعه تذكير أسعد\nوصل أُسيد بن حُضَيْر عندهم وهو متحفز للخناقة معاهم وقال لهما : \nإنتم إيه إللي جابكم هنا، امشوا من هنا لو خايفين على نفسكم \nالكلام شديد ومستفز لكن مصعب الهادئ الحليم قال له بكل هدوء: \nإيه رأيك تقعد تسمع، لو عجبك الكلام اقبله معجبكش هنمشي ومش هنقول لك حاجة تكرهها\nفقال أُسَيد بن حضير : صح معاك حق \nوراح قاعد يسمع وهو ساند على الحربة بتاعته، بدأ مصعب يتكلم عن الإسلام وإنه بيدعو للتوحيد ومكارم الأخلاق،\nوقرأ عليه آيات من القرآن،\nفبدأ وجه أسيد يتغير ...الوجه الغضبان بدأ يتغير ويظهر عليه علامات الإعجاب بكلام الله وظهرت علامات الهدوء والسكينة على وجه أسيد\nوتأثر جدا لدرجة إن أسعد قال : والله احنا عرفنا وشوفنا الإسلام في وجهه قبل ما يتكلم\n☆سبحان الله الوجه مرآة القلب فعلا، الإنسان كل ما قلبه يكون نقي وعنده خشية لله ومتأثر بالله هتلاقي ده في وجهه\nيعني تخيلوا إن رجل دخل الإسلام لمجرد إنه شاف وجه رسول الله ﷺ، \nلما شافه قال إن وجهه مش وجه كذاب أبدا فأسلم على طول\nلأن إللي بيتعمل في الخفاء بيبان، من أسر سريرة ألبسه الله رداءها علانية ، إن خيرا فخير وإن شرا فشر،\nيعني إللي يطيع ربنا في الخفاء هتلاقي ربنا أظهر طاعته دي على هيئة نور وقبول في وجهه،\nومن عصا الله في الخفاء هتلاقي على وجهه سواد وعدم القبول وتبقي مش طايقة تبصي في وجه الشخص ده ولا تكلميه، كده بدون سبب\nفكان واضح على وجه أسيد الإسلام فسألهما أسيد : \nهو إللي عايز يدخل الدين ده يعمل إيه\nفقال له مصعب رضي الله عنه:\nتقول الشهادتين وتغتسل وتطهر ثيابك وتصلي ركعتين،\nفي نفس اللحظة قال الشهادتين واغتسل وصلى،\nبكل سهولة كده غير دينه إللي عاش عليه سنين ولا كأنه بيغير هدومه\nمفكرش في صاحبه وصديق عمره إللي مستنيه وإنه ممكن يخسره،\nمفكرش في أهله وعيلته ورد فعلهم ولا فكر في مكانته إللي ممكن تروح بسبب إسلامه وهو سيد من سادات الأوس،\nمتخيلين يعني إيه واحد يغير دينه\nالبنت لما تيجي تلتزم بالدين أو الحجاب الشرعي تلاقيها بتفكر مائة مرة،\nأصحابي هيبعدوا عني، وأمي وأبويا والمشاكل و...و...وأعذار مش بتخلص،\nوده مجرد ما سمع القرآن غير دينه كله مستناش يشوف ظروفه تسمح ولا لأ، مستناش يقول هو أنا هقدر أكمل في الدين ده ولا لأ،\nعرفتم ليه الصحابة مختلفين عن أي حد تاني، الصحابة كان ييجي لهم الأمر ينفذوا فورا، الواحد منهم مجرد ما يسمع كلام ربنا كان يسلم فورا وميهموش أحد\nشوفوا أسيد بن حضير بعد إسلامه على طول عمل إيه\nقال لمصعب وأسعد بن زرارة:\n في واحد لو أسلم محدش من قبيلته هيتخلف عنه..كل قبيلته هتسلم وأنا هقول لكم عليه\nاشتغل داعية مجرد ما أسلم، شال هم الإسلام وحس إنه بتاعه ولازم ينشره، \nوهو ده الفرق بين المسلم الحقيقي والمسلم بالاسم، عارفين الإسلام هينتصر ويسود الدنيا امتى؟\nلما كل واحد فينا يحس إن الإسلام ده بتاعه ولازم ينشره وينصره ويدافع عنه، مش مستني الشيخ فلان يقول ويعمل،\nولا مستني الشيخ علان هو إللي يتحرك\nأسيد بن حضير بمجرد إسلامه راح لصاحبه سعد بن معاذ عشان يجيبه يدخله الإسلام\nأول ما رآه سعد مقرب عليه وشاف وجهه قال للناس إللي قاعدين معاه :\n والله أُسيد راجع بغير الوجه إللي مشي بيه\n☆طبعا الوجه مختلف، راح بوجه كافر ورجع بوجه مسلم بيشع نور \nفلما وصل عنده سأله سعد : عملت إيه\nفألف أسيد قصة عشان يجيب رجل سعد ويخليه يروح لمصعب وأسعد\nطبعا هو مكنش يعرف إن الكذب حرام في الإسلام\nفقال لسعد بن معاذ وكان سعد زوج عمة أسيد بن حضير:\nوالله الناس طلعوا طيبين وبيسمعوا الكلام قلت لهم امشوا قالوا حاضر هنمشي\nلكن أنا عرفت إن بني حارثة خرجوا عشان يقتلوا أسعد لأنهم عرفوا إنه ابن خالتك فعايزين يُهينوك بقتله\nفقام سعد وأخذ معاه الحربة وراح يشوف الحكاية، فوهو جاي ناحيتهم أسعد شافه وقال لمصعب : \nشوف الرجل إللي جاي هناك ده، الرجل ده سيد قومه ولو اتبعك كل قومه هيتبعوك ومحدش هيتخلف عنه\nفلما وصل سعد عند أسعد ومصعب لقاهم قاعدين ومستأنسين ومفيش مشاكل ومفيش بني حارثة ولا أي حاجة فعرف إن أسيد ضحك عليه عشان يروح لهم\nكأني أنظر لسعد وهو بينظر لأسيد بن حضير بنظرات معناها : بقى كده ماشي\nوأسيد بن حضير بيبص الناحية التانية ولا كأنه هنا \nفمكنش قصاده غير إن هو إللي يتصرف ويطردهم فتجاهل مصعب ووجه الكلام لأسعد قال له:\nوالله يا أبا أمامة لولا إللي بيني وبينك من صلة القرابة لكان هيبقى لي معاك تصرف ثاني، إنت جاي تؤذينا في دارنا\nفتدخل مصعب رضي الله عنه في الحوار وقال له بكل هدوء:\nإيه رأيك تقعد تسمع، فلو عجبك الكلام قبلته، لو معجبكش خلاص، هنبعد عنك \nفقال سعد: صح عندك حق، أنصفت في الكلام\nفقعد سعد بن معاذ وهو ساند على الحربة بتاعته يسمع كلام مصعب،\nشرح له مصعب الإسلام والقواعد الأساسية بتاعته إللي احنا قلناها في الجزء إللي فات وقرأ عليه القرآن،\nتأثر سعد بن معاذ بالكلام وظهر على وجهه التأثر ،وقال أسعد بن زرارة : \nوالله عرفنا الإسلام في وجهه قبل ما ينطق\nقال سعد بن معاذ : يعمل إيه إللي عايز يدخل في الإسلام\nبكل بساطة أخذ قرار الدخول في الإسلام\nقال له مصعب: \nتقول الشهادتين وتغتسل وتطهر ثيابك وتصلي ركعتين،\nفعمل كده في نفس اللحظة وبقى مسلم\nيسكت\nعمل حاجة عجيبة جدا\nراح سعد لقبيلته وجمعهم وقال لهم:\nيا بني عبد الأشهل!\nكيف تعلمون أمري فيكم ؟ يعني إيه رأيكم فيّ\nفقالوا له:\nده إنت سيدنا، ورأيك أحسن رأي فينا \nفقال لهم سعد : \nمحدش يتكلم معايا لا رجال ولا نساء ولا لي علاقة بكم لحد ما تؤمنوا بالله ورسوله\nهو بيعرّض ملكه ومكانته ووضعه الإجتماعي للخطر،\nهم ممكن يقولوا له خلاص مش عايزينك هنجيب غيرك مش صعبة هي، إنت بتهددنا،\nهو فعلا أد كلمته، هو عنده استعداد يتنازل عن أي شيء في الدنيا في مقابل الإسلام، فعلا مش فارق معاه أي حاجة\nوإللي بيَصدق مع ربنا وبيكون همه رضا الله فقط ربنا بيجمع له شمله ويحقق له أكثر مما يتمنى\nالنتيجة كانت مُبْهرة، كل قبيلة سعد بن معاذ أسلمت ماعدا رجل واحد تأخر إسلامه أسلم بعد أربع سنين\nاحنا مش بنقول عشرة ولا عشرين احنا بنقول قبيلة كاملة تسلم في لحظة واحدة،\nده احنا كنا لسه عدد بسيط وضعفاء مستضعفين معذبين، \nفي لحظة بقينا مئات\nقبيلة كاملة برجالها ونسائها وأطفالها وسلاحها وخيولها وأموالها بقت تحت تصرف الإسلام\nهل مصعب كان يتوقع ولا يحلم وهو معذب في مكة ولا مطارد في الحبشة إن هتيجي اللحظة إللي تدخل فيها قبيلة قوية زي قبيلة الأوس في الإسلام\nربنا بيعلما إن التمكين بإيده هو، احنا علينا بذل الأسباب فقط،\nمطلوب نعمل إللي في إيدنا ونقدر عليه، سواء شفنا النتيجة ولا لأ، مصعب شاف نتيجة دعوته،\nلكن سمية وياسر مشفوش نتيجة تضحيتهم، ربنا هيسألنا عن إللي احنا قدمناه وإللي احنا نقدر عليه، مش هيسألنا عن النتائج أبدا\nنتعلم من قصص النهاردة إن الصدق مع الله وإخلاص النية مع بذل المجهود، يعني نعمل إللي نقدر عليه... هو السبيل الوحيد لنصرة الإسلام\nالوضع اتغير في المدينة، كله بقى شغال في الدعوة ونشر الإسلام، وصل الإسلام لكل بيت في يثرب مفيش بيت إلا ودخل بعض أفراده الإسلام،\nكل ده خلال سنة واحدة وهي السنة الثالثة عشرة للبعثة،\nقبل موسم الحج رجع مصعب بن عمير لرسول الله ﷺ في مكة عشان يشرح له الوضع في يثرب بقى عامل إزاي بعد إسلام الناس،\nشرح له الوضع في المدينة ، ووضح له قوة رجال أهل يثرب وكرمهم،\nشرح مصعب لرسول الله ﷺ كل شيء كأنه كان معاهم السنة دي كلها\nبرغم إن دعوة مصعب بن عمير كانت علانية والناس كلها سمعت عن الإسلام حتى اليهود إللي كانوا ساكنين في يثرب، إلا إن إللي كان بيُسلم مكنش بيعلن إسلامه،\nيعني عشان ظروف يثرب ووجود مشركين فيها لسه وكمان اليهود،\nفكانوا مراعين لظروف البلد، الدعوة كانت علنية لكن التربية وتعلم الدين كان سري\nوالسرية في الوقت ده مطلوبة، احنا لسه مش عارفين إيه إللي ممكن يحصل، فكل ماكانت الأمور مخفية كل ماكان ده في صالحنا\nوعلى فكرة النقطة دي مهمة حتى في أمورنا الحياتية،\nطول ما الإنسان محافظ على أسرار نفسه، هيحمي نفسه من حاجات كتير أوي،\nهيحمي نفسه من نظرة حاسد، من كلام الناس عليه،\nمن مشاكل ممكن يضع نفسه فيها،\nحتى رسول الله ﷺ قال:\n\"استعينوا على إنجاح الحوائج بالكتمان فإن كل ذي نعمة محسود\"\n《الحديث صححه الألباني》\nوطبعا ده لا يتعارض مع أما بنعمة ربك فحدث\nفالمقصود منها إن القيام بشكر النعمة وإظهار أثارها، يعني لو الإنسان ربنا رزقه بأموال يشكر ربنا عالنعمة دي، \nويتصدق كثير ويكون كريم مع الناس،\nمش إنه يروح يقول للناس انا عندي وعندي \nرسول الله ﷺ معملش كده\nفكل ما كان الإنسان يخفي أموره عن الناس كل ما كان في مأمن\nتخيلي لو حصلت مشكلة مع واحدة وإنتي كنتي قايلة لها على أسرارك وهي من غيظها منك راحت فاضحاكي،\nموقفك هيبقى إيه ساعتها\nوحصلت وأكيد شوفتم مثال ولا اثنين قصادكم، فنصيحة اكتموا من أموركم على أد ما تقدروا عشان متعرفوش المستقبل فيه إيه\nواحنا هنشوف نتيجة كتمان المسلمين إسلامهم ساعدهم إزاي لما اتقابلوا مع رسول الله ﷺ في بيعة العقبة الثانية \nجاء موسم الحج من السنة الثالثة عشرة للبعثة ،وسافر من يثرب لمكة وفد عشان يحجوا وكان عددهم ثلاثمائة إنسان،\nكان في الوفد ده خمسة وسبعون مسلم،\n ثلاثة وسبعون رجل وامرأتان، ومكنش حد من المشركين إللي كانوا في الوفد يعرفوا المسلمين إللي معاهم\nوالسبب إللي خلى الخمسة وسبعين مسلم دول يروحوا يقابلوا رسول الله ﷺ، \nإن جابر بن عبد الله وكان واحد من الستة إللي أسلموا في البداية قال لأصحابه : \nهو احنا هنفضل سايبين رسول الله ﷺ يطرد في جبال مكة والناس تؤذيه لحد امتى\nفجمعوا بعض وراحوا عشان يقابلوه عشان ينصروه ويقنعوه إنه يروح معاهم ليثرب، يعني هم إللي سعوا في نصرة رسول الله ﷺ قبل ما هو يطلب منهم\nفرق كبير بين إللي بيبحث عن الدعوة ونصرة الدين، وبين إللي الناس بتدور عليه عشان ينصر الدين\nرتب الوفد المسلم مع رسول الله ﷺ مكان و ميعاد عشان يتقابلوا فيه ويتكلموا،\nهيتقابلوا فين وإيه الحوار إللي دار بينهم، ده إللي هنعرفه الجزء الجاي إن شاء الله\n☆"}, {"n": 69, "l": "الجزء 43 | بيعة العقبه الثانيه", "u": "https://www.facebook.com/groups/710210019782034/permalink/783319615804407/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة_والأربعون\n#بيعة_العقبة_الثانية\nاتكلمنا المرة إللي فاتت عن إسلام أُسَيد بن حضير وسعد بن معاذ وشفنا إزاي في خلال سنة واحدة انتشر الإسلام في يثرب،\nووقفنا عند وفد المسلمين إللي جاء لمكة عشان يقابل رسول الله ﷺ عشان ينصروه ويدعوه إنه يروح معاهم ليثرب،\nوقلنا إنهم كانوا ثلاثة وسبعين رجلا وامرأتين،\nبدأ الترتيب بين رسول الله ﷺ  ووفد المسلمين من يثرب، هو محتاج يقابل الخمسة وسبعين كلهم، \nيعني مينفعش يقابل نصهم مثلا لأنهم وإن كانوا من قبيلتين إللي هم الأوس والخزرج،\nإلا إن القبيلتين فيهم بطون كثيرة، يعني عائلات وفروع كثيرة، وممكن ناس توافق على الشروط وناس لأ\nفهيكون الموقف إيه لو رسول الله ﷺ راح يثرب واكتشف إنهم مش أد المسؤولية أو فيهم ناس معترضة على الإتفاق إللي حصل بينه وبين بعضهم\nفلازم رسول الله ﷺ يقابلهم كلهم ويطمن بنفسه إن كلهم موافقين على الإتفاق إللي هيتم،\nرسول الله ﷺ بيحسب كل خطوة بمنتهى الدقة\nمينفعش في المرحلة دي يكون في أي خطأ لأن احنا بنحط أساس لقيام دولة الإسلام،\nوانتم عارفين إن أهم حاجة في أي بناء هو الأساس\nعشان كده ربنا جعل للإنسان بالذات اثنا عشرة سنة على الأقل قبل البلوغ ليس عليه حساب ،\nعشان يتأسس صح  ويقدر يؤدي تكاليفه ومسؤولياته بعد مرحلة البلوغ\nطيب العدد كبير ومكة صغيرة هيتقابل معاهم إزاي وفين من غير ما أي أحد يعرف، احنا محتاجين السرية التامة زي ما قلنا المرة إللي فاتت\nشوفوا عبقرية رسول الله ﷺ وتخطيطه الدقيق عشان نتعلم منه\n♡أولا:\nاختار رسول الله ﷺ إن الميعاد يكون في ليلة ثلاثة عشر يعني آخر ليلة في موسم الحج،\nلأن ثاني يوم الحجاج هيرجعوا لبلادهم، فلو أحد من قريش عرف أي حاجة عن اللقاء ده، مش هيقدروا يوصلوا للوفد إلا بعد ما يكونوا مشيوا\n♡ثانيا: \nرسول الله ﷺ خلى ميعاد اللقاء في الثلث الأوسط من الليل، لأن في الغالب كل الناس هتبقى نايمة في الوقت ده\n♡ثالثا:\nبالنسبة للمكان ، اختار رسول الله ﷺ مكان بعيد عن زحمة الحجاج ومفيش حد من الحجاج حاطط خيام فيه، اختار الشِّعب الأيمن من العقبة\n♡رابعا:\nرسول الله ﷺ مقلش لأحد من المسلمين على اللقاء ده\nيعني محدش عرف نهائي غير ثلاثة فقط، \nالعباس عم رسول الله ﷺ وكان في الوقت ده مشرك ولكن كان هيشارك في الإجتماع،\nوأبو بكر الصديق وعلي بن أبي طالب عشان يراقبوا مكان الإجتماع\nورسول الله ﷺ أخفى على المسلمين مش عشان هو شاكك فيهم أو بيخونهم، لأ...لكنه عايز اللقاء يكون في سرية تامة،\nفاللي ملوش علاقة بالموضوع يعرف ليه\n☆وده يعلمنا إننا منزعلش لما حد يخبي علينا حاجة متخصناش أو مفيش فايدة في معرفتها\nيعني لما المسلمين هيعرفوا بعدين باللقاء إللي حصل، مفيش حد هيقول لرسول الله ﷺ إنت ليه مقلتناش يا رسول الله،\nهو احنا يعني هنفشي سرك ولا هنقول لحد\nمش كان لازم تعرفنا مش احنا برده في مركب واحدة ولازم نكون عارفين كل حاجة\nبالعكس محدش اعترض لأن مش كل حاجة لازم يعرفوها وهم عارفين إن رسول الله ﷺ  مش هيعمل حاجة إلا وهي في مصحلة الإسلام والمسلمين \nورسول الله ﷺ قال للوفد إللي هيقابله ياخدوا بالهم وينتبهوا هم كمان عشان محدش من الناس المشركين إللي معاهم يحس بيهم\nعمل إيه الوفد\nبيحكي كعب بن مالك وهو واحد من الوفد المسلم بيقول:\nاحنا نمنا مع قومنا عادي في المكان المخصص بتاعنا،\nولما ميعاد اللقاء قرب،\n كل واحد بدأ يتسلل...يتسحّبوا يعني واحد وراء التاني لحد ماتجمعوا في المكان إللي اتفقوا عليه\nاجتمع الوفد وجاء رسول الله ﷺ ومعاه العباس وأبو بكر الصديق وعلي بن أبي طالب في الميعاد المحدد وبدأ الإجتماع إللي هيغير خريطة الأرض كلها\nطبعا السؤال المُحير هنا هو إزاي رسول الله ﷺ يجيب معاه واحد مشرك في اجتماع مهم زي ده\nقلت لكم إن رسول الله ﷺ مش بياخد أي خطوة إلا بحساب\nالعباس بن عبد المطلب له دور سياسي مهم، المسلمين من يثرب هدفهم إنهم يأخذوا رسول الله ﷺ، \nفلازم يعرفوا إن رسول الله ﷺ له قبيلة ذات شرف، فهم لما يأخذوه عندهم لازم يكونوا هم البديل للقبيلة دي\n¤ممكن حد يقول طيب ما كان يأخذ حمزة ماهو عمه وبرده مسلم\nماهو لو كان أخذ حمزة رضي الله عنه كان هيترسخ في ذهن الوفد إن حمزة جاء عشان هو مؤمن مش عشان بيمثل بني هاشم،\nلكن لأن العباس مشرك فده بيوصل لهم معلومة وهي إن بني هاشم مؤمنهم وكافرهم مع رسول الله ﷺ\nوخلونا نشوف كلام العباس لوفد المسلمين من يثرب \nقال العباس :\nيا معشر الخزرج!\n=العرب كانت بتسمي أهل يثرب كلهم من الأوس والخزرج خزرجا=\nمكانة محمد فينا زي ما إنتم عارفين، واحنا دافعنا عنه ضد قومنا، فهو عزيز في قومه ومنيع في بلده، لكنه هو إللي مصمم إنه يسيبنا ويروح عندكم\nفلو إنتم شايفين إنكم هتقدروا توفُّوا إللي وعدتوه به وتحموه من إللي يخالفه، خلاص إنتم حرين،\nلكن لو إنتم هتتخلوا عنه بعدين فسيبوه من دلوقتي، فهو في عزة ومنعة من قومه\nطبعا وفد المسلمين من يثرب في الموقف ده الطبيعي إنه يردوا على العباس رد محترم يجيبوا له فيه القديم والجديد\nزي مثلا:\nإنت بتقول عزة ومنعة \n عزة إيه ومنعة إيه وهو في حماية المطعم بن عدي الكافر إللي من قبيلة تانية غير قبيلة بني هاشم\nبتقول إن رسول الله ﷺ هو إللي صمم إنه ييجي عندنا ويسيبكم ويسيب الحماية الفظيعة إللي إنتم موفرينها له\nكنتم فين لما ضُرب ورُمي بالحجارة واتشتم واتحط على ظهره أمعاء البعير،\nوياريتكم كنتم ساكتين\nده أبو لهب كان بيمشي وراه ويكذبه وسط الناس كلها\nكان ممكن الكلام ده يتقال وأكثر منه لو دي حاجة خاصة بالدنيا ومفاوضات هدفها مصالح،\nلكن الوفد الإسلامي من يثرب كان همه نصرة رسول الله ﷺ، عايزين يكونوا أتباع رسول آلله ﷺ وتحت أمره هم جايين المسافة دي كلها عشان كده،\nردوا بكلمتين على العباس قالوا:\nاحنا سمعنا إللي قلته\n اتكلم إنت بقى يا رسول الله وقول إللي إنت عايزه لنفسك ولربك \nدي فرصة متتعوضش، أخيرا في ناس عندهم استعداد يعملوا أي حاجة لرسول الله ﷺ \nأخيرا جت الفرصة إنه يروح يقعد في مكان يكون فيه عزيز هو الآمر الناهي،\nالمفروض بقى رسول الله ﷺ يحط شروط معقولة إكراما للناس إللي هيستضيفوه دول\nلكن الوضع كان مختلف، رسول الله ﷺ هيقول لهم شروط شاقة جدا مطلبهاش من حد قبل كده عشان هو يقبل إنه يروح عندهم، مع إنه هو إللي محتاج\nقال لهم تبايعوني على:\n◇ السمع والطاعة في النشاط والكسل، طيب سهل إن الإنسان يسمع ويطيع في النشاط، \nلكن لما يكون كسلان ومش عايز يعمل حاجة، الموضوع مش بيكون بإيده، \nتخيلي لما تكوني مكسلة في البيت وحد بيطلب منك حاجة إنتي أصلا بتبقي مش عايزة تعملي حاجة لنفسك،\nفتخيلي لما حد يطلب منك حاجة\nفرسول الله ﷺ  بيقولهم تسمعوا كلامي في وقت النشاط وفي وقت الكسل زي بعض\n◇ النفقة في العسر واليسر، يعني وقت مانكون محتاجين فلوس تساعدوني سواء عندكم أموال كثيرة أو قليلة\n◇ الأمر بالمعروف والنهي عن المنكر، مفيش حاجة اسمها مليش دعوة، مفيش حاجة اسمها أصل الناس هتشتمني أصل الناس مش هتقتنع أصل...أصل...\n◇ أن تقوموا لله لا تأخذكم في الله لومة لائم، يعني تقولوا كلمة الحق مهما كان\n◇أن تنصروني لو أنا جيت عندكم، وتحموني زي ما بتحموا أنفسكم وأزواجكم وأبنائكم،\nيعني مش حماية عادية كده وخلاص، ده إنتم هتدافعوا عني زي ما بتدافعوا وتحموا نفسكم وأهلكم، \nيعني باختصار حبكم لي يكون أكثر ما بتحبوا نفسكم أو أحد تاني\n التشديد ده من رسول الله ﷺ ليه\nلأن هو عايز يبني أمة، في فرق بين إنسان صالح عايش لنفسه ولأسرته، \nوإنسان تاني صالح لكن كل تفكيره في أمته، مش قادر ينام وهو شايف الظلم والكفر حوله، \nلو شاف حد يمس الإسلام بسوء يقوم يدافع عنه زي ما بيدافع عن زوجته أو ابنه،\nهو ده الشخص إللي رسول الله ﷺ  كان عايز يبنيه، تخيلوا لما تكون أمة كاملة تفكيرها كده الوضع هيبقى عامل إزاي،\nمش مجرد عشرة ولا عشرين واحد وسط مليون \nتخيلوا إن الصحابة كلهم بلا استثناء كل واحد فيهم بقى أمة لوحده، كان شخصية عظيمة لوحده،\nفلما يتجمع العظماء كلهم مع بعض هيعملوا إيه\nوده يبين لنا الفرق بين بيعة العقبة الأولى وبين بيعة العقبة الثانية،\nبيعة العقبة الأولى رسول الله ﷺ كان بيبني شخصية إنسان مسلم عادي فيه القواعد الأساسية،\nلكن لما نكون عايزين نبني أمة..نبني دولة فاحنا محتاجين لبذل وعطاء وتضحيات وصبر وقوة تحمل،\nعايزين مسلمين من نوع خاص جدا، مسلمين يدافعوا عن الإسلام وحرماته، مسلمين يبذلوا كل طاقتهم في نشر الإسلام في كل مكان،\nهي دي الشخصيات إللي كان رسول الله ﷺ عايزها عشان تكمل معاه وبعده المشوار بتاعه\nكان إيه بقى رد فعل الوفد المسلم على كلام رسول الله ﷺ \nالطبيعي إنهم يتناقشوا ، يقولوا مثلا طيب احنا هنقدر على كذا ومش هنقدر على كذا،\nطيب شيل الشرط ده ونتناقش في ده، لكن محدش فيهم اعترض\nرئيس الوفد المسلم بدأ يتكلم وكان اسمه :\n《البراء بن مَعرُور》\nقال لرسول الله ﷺ:\nوالذي بعثك بالحق لنَمْعنّك ونحميك زي ما بنحمي نسائنا ، فبايعنا يا رسول الله\nفوالله احنا أبناء الحرب، يعني احنا أقوياء متقلقش\nهو إللي بيتحايل على رسول الله ﷺ عشان يقبل بالبيعة\nوكان هو أول واحد حط إيده في إيد رسول الله ﷺ عشان يبايعه على نصرته والجهاد معاه ضد أي أحد يعتدي عليه\n☆عارفين البراء بن معرور ده\n مات قبل ما رسول الله ﷺ يهاجر ليثرب بشهر واحد\nيعني مات بعد مبايعته دي بشهرين تقريبا، وعارفين كمان لما لقى نفسه هيموت وهو لسه موفّاش بأي حاجة من إللي وعد بها رسول الله ﷺ عمل إيه؟\nأوصى بثلث ماله لرسول الله ﷺ يتصرف فيه زي ماهو عايز،\nكأنه بيقول يا رسول الله أنا مقدرتش أوفي ببيعتي...غصب عني...لكن على الأقل خذ مالي...أي حاجة أساعدك بها\nربّاه إني قد وهبْتُ حياتي    ومَنَحْتُ عمري للهُدى ومَمَاتي فاقبل إله العرش مني بَيْعتي    يا من إليك أبُوحُ بالعبراتِ    \nفي وسط ما كان البراء بن معرور بيكلم رسول الله ﷺ  وبيقنعه قاطعه واحد من المسلمين إللي أسلموا في بيعة العقبة الأولى وهو أبو الهيثم بن التيّهان،\n وقال لرسول الله ﷺ:\nشوف يا رسول الله..احنا عندنا عهود ومواثيق بينا وبين اليهود إللي عايشين معانا في يثرب، واحنا هنقطع عهودنا معاهم،\n فهل لو احنا عملنا كده وبعدين ربنا أظهرك ونصرك هترجع لقومك وتسيبنا \nممكن حد يفكر إن الإعتراض ده فيه تطاول على رسول الله  ﷺ وإنه إزاي يفكر كده برسول الله ﷺ  وهو صاحب الأخلاق العالية\n لكن الوضع كان غير كده، أبو الهيثم كان متأكد إن رسول الله ﷺ مش هيسيبهم ويتخلى عنهم، \nبس هو حب إن رسول الله ﷺ يقول كلام يطمّن به أي حد في قلبه شك وخايف من المستقبل وبكده يقفل كل أبواب الشيطان\nفرسول الله ﷺ تبسم وقال له:\n\"بل الدم الدم والهدم الهدم، أنا منكم وأنتم مني أحارب من حاربتم وأسالم من سالمتم\"\nيعني رسول الله ﷺ  بيقول لهم إني دمي هو دمكم وأنا منكم إللي هتحاربوه أحاربه، وإللي تسالموه أنا أسالمه،\nمع إن الاتفاق إنهم إللي يحاربوا مع رسول الله ﷺ عشان ينشروا ويدافعوا عن الإسلام،\nلكن رسول الله ﷺ طمنهم إن لو أي أحد هجم عليهم عايز يؤذيهم هيحارب معاهم ويدافع عنهم\n☆شوفوا رسول الله ﷺ بيعلمنا حاجة مهمة جدا\nوهي إن القائد لا ينقص من قدره شيء لو جندي من جنوده اعترض عليه وحب يستفهم، \nيعني بيقول لنا بطريقة عملية اسمعوا لآراء إللي حواليكم حتى لو كانوا أقل منزلة، \nطمنوهم ...حسسوهم إن القيادة غير مفروضة عليهم وإن الموضوع مش حاكم ومحكوم وقائد وجندي،\nلكن أنا منكم وأنتم مني\nبيعلمنا رسول الله ﷺ إن أي إنسان عادي جدا إننا نناقشه ونستفهم منه، \nاحنا بشر والبشر ممكن يغلطوا وحتى لو مفيش غلط إيه المشكلة لما نعرف وجهة النظر عشان نستفيد ويمكن كمان نضيف ونتوصل مع بعض لحلول أفضل،\nوده هيعطي الجندي إحساس إن القائد بتاعه حاسس بيه وبيشاركه في ألمه وتفكيره،\nفهتلاقي الجندي بيبذل كل طاقته وهو مبسوط ويجيب أخره، بعكس المُجبَر\nالإسلام مفيهوش اعمل زي الآلة ومتفتحش بؤك\nوده لا يتعارض مع إن لما ييجي لنا الأمر من الله ورسوله ننفذ فورا\nدي غير دي خالص\nوالعلاقة إللي قلناها دي مش بس بين القائد وجنوده، دي كمان بين الأم و الأب وعيالهم وبين الزوج وزوجته، حتى بين الأصحاب\nمتقوليش لابنك ولا بنتك اعمل إللي أقول لك عليه وخلاص\nولو جه يستفهم منك تصديه بحجة إنه مش هيفهم، ولا يعترض وعنده رأي تاني وإنتي متسمعيش رأيه\nولا تطلبي منه حاجة من غير ما تساعديه فيه وتعلميه معنى التعاون وبعدين تيجي تشتكي ده العيال مش بيساعدوني وتاعبيني\nهل إنتي علاقتك باللي حواليكي زي علاقة رسول الله ﷺ كده مع إللي حواليه أيا كنتي سواء أم.. زوجة... صاحبة،\nولا علاقتك بيهم علاقة تسلط واعملوا إللي أنا شايفاه صح ومحدش يناقشني وأنا عارفة أنا بعمل إيه\nبناء الأمة الإسلامية بيبدأ ببناء الأفراد، \nكل واحد فينا لو حط نموذج تعامل رسول الله ﷺ قصاده وبدأ يطبقه على أد ما يقدر وضعنا هيختلف أكيد\nلما رسول الله ﷺ قال الكلام ده لوفد المسلمين من المدينة استبشروا وراحوا قايمين عشان يبايعوا رسول الله ﷺ، \nلكن واحد منهم قال لهم : استنوا ..استنوا\nإنتم عارفين إنتم بتبايعوا على إيه \nفقالوا له : أه عارفين\nفقال لهم: يا جماعة إنتم بتبايعوه على حرب الأحمر والأسود من الناس، يعني بتبايعوه على حرب كل الناس إللي في الارض، \nفلو إنتم أموالكم خلصت وقتل أشرافكم ونويتم تتخلوا عنه، فمن دلوقتي سيبوه يشوف غيركم\nلأنكم لو تخليتم عنه بعد كده هيبقى خزي الدنيا والآخرة\nلكن لو هتقدروا تكملوا على الرغم من المصائب إللي هتخصل لكم، خلاص كملوا فهذا خير الدنيا والآخرة\nهو كان بيقول لهم كده عشان لو في حد مش فاهم والرؤية عنده مش واضحة يفهم، عشان محدش ييجي بعد كده ويقول لأ ..أصل أنا مكنتش فاهم إن الموضوع ممكن يوصل للدرجة دي\nالموضوع مفهوش تهريج خالص، الناس دي هتقف قصاد كل أهل الارض\nفقالوا :خلاص عادي احنا هنأخذه حتى لو فقدنا أموالنا وأشرافنا\nولسه هيبايعوا راح أسعد بن زرارة ماسك يد رسول الله ﷺ و قايل لهم :\n استنوا \nبراحة كده وافهموا، احنا مش جايين من يثرب إلا واحنا عارفين إنه رسول الله،\n لكن معنى إنكم هتخرجوه من بلده يعني هتقطعوا علاقاتكم بكل العرب، وأحسن ناس فيكم هتموت، \nفلو هتقدروا تصبروا على كده خلاص خذوه ، مش هتقدروا سيبوه من دلوقتي\nأسعد بن زرارة عارفينه طبعا وعارفين نشاطه في نشر الدعوة\nهو بيأكد تاني على نفس المعنى ، يعني يا جماعة آخر تحذير، مفيش رجوع وقت ما تبايعوا، اتأكدوا كويس،\nلكنهم كانوا واثقين من قرارهم وعايزين ينصروا رسول الله ﷺ  بأي طريقة \nلكنهم سألوا رسول الله ﷺ سؤال مهم جدا\nقالوا : يارسول الله! لو احنا وفّينا بكل إللي اتفقنا عليه، \nإيه هو جزاءنا\nقال لهم رسول الله ﷺ : جزاؤكم 《الجنة》 \nالثمن لكل التضحيات إللي هتضحوا بها هو الجنة، مفيش وعد لا بدولة ولا نصر ولا تمكين ولا أي حاجة،\nالنصر والتمكين هييجي في يوم من الأيام، لكن إنت ممكن تموت قبلها \nفمفيش جزاء لكم غير الجنة\nأول ما سمع المسلمين كلام رسول الله ﷺ قالوا:\nرضينا، لا نقيل ولا نستقيل\nيعني يا رسول الله لا احنا هنرجع في كلامنا ونندم، ولا إنت تطلب إلغاء الإتفاق\nفنزلت آية:\n\"إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ ۚ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ \nوَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالْإِنجِيلِ وَالْقُرْآنِ ۚ \nوَمَنْ أَوْفَىٰ بِعَهْدِهِ مِنَ اللَّهِ ۚ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذِي بَايَعْتُم بِهِ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ\"\nرسول الله ﷺ طلب من الوفد الإسلامي إنهم يتفقوا ويختاروا من بينهم مجموعة يقدر رسول الله ﷺ يتعامل معاهم ويتكلم معاهم،\nلأنه صعب إنه يكلم السبعين مرة واحدة\nفقال لهم من كل ستة طلعوا لي واحد، مع إن رسول الله ﷺ كان ممكن هو إللي يختارهم، لكنه بيعلم الصحابة واحنا من بعدهم إن الناس من حقها تختار إللي يمثلها،\nلأن لما الناس هي إللي تختار هيسمعوا ويطيعوا للي اختاروهم،\nتخيلوا لما يكون الشخص مفروض عليكي ويقول لك اعملي ومتعمليش، أقل كلمة هنقولها وإنت أصلا مين إداك الحق إنك تاخذ قرار بدالي ولا تقولي اعمل ومتعمليش\nفرسول الله ﷺ بيعلمهم من أول يوم التعاون وإزاي يتفقوا وإزاي يختاروا صح\nقعد الأوس والخزرج مع بعض لأول مرة بعد قتال سنين، عشان يختاروا من يمثلهم أمام رسول الله ﷺ، \nبعد مبايعة الإثنا عشر نقيب لرسول الله ﷺ سمعوا صرخة عظيمة\nمين إللي صرخ ده ، وقال إيه \nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡مش هقدر أطول أكثر من كده عشان في ناس عينها بتتعب من البص في الموبايل"}, {"n": 70, "l": "الجزء 44 | هجر المسلمون الي يثرب", "u": "https://www.facebook.com/groups/710210019782034/permalink/786101642192871/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والأربعون\n#هجرة_المسلمين_ليثرب\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما كان قاعد مع وفد المسلمين من يثرب، وشفنا البيعة إللي حصلت،\nواختار الوفد المسلم من بينهم اثنا عشر رجلا عشان يكونوا مسؤولين عن كل الوفد ويمثلوا كل المسلمين إللي في يثرب،\nوقال لهم رسول الله ﷺ :\nإنتم المسؤولين قصادي عن كل المسلمين في يثرب، وأنا المسؤول على المسلمين من أهل مكة،\nفقالوا : ماشي اتفقنا \nوطلب رسول الله ﷺ من الاثنا عشر رجل إنهم يختاروا  واحد منهم يكون رئيسهم عشان التواصل والمتابعة يبقى سهل\nرسول الله ﷺ مش بس بيعلمنا إزاي نخطط ونرتب وناخد بالأسباب ، ده كمان بيعلمنا فن الإدارة وتنظيم الأمور،\nمش كل حاجة سايحة على بعض\nكل واحد له مسؤولية محددة \nاختاروا أسعد بن زرارة يكون هو رئيسهم\nوبعد ما خلاص اتفقوا وكل حاجة تمام ، سمعوا صرخة عظيمة جدا، صوت عالي جدا بيقول:\nيا أهل الجَبَاجِب، هل لكم في مُذَمّمٍ والصُّبَاةُ معه قد أجمعوا على حربكم\nيعني يا أهل المنازل أو يا أهل الخيام، يقصد أهل مكة،\nإلحقوا مذمم اجتمع مع الصابئين إللي غيروا دينهم عشان يحاربوكم،\n ومذمم يقصد به رسول الله ﷺ لأنهم غيروا اسمه من محمد لمُذَمّمٍ، نوع من أنواع الأذى إللي كان بيتعرض له رسول الله ﷺ، حتى كان من أدب رسول الله ﷺ  ونظرته الإيجابية للموضوع، كان يقول : \nشوفوا ربنا بيصرف عني أذى قريش إزاي، بيدعوا على مذمم وبيشتموا مذمم وأنا محمد\nفرسول الله ﷺ لما سمع الصرخة قال : \nهذا شيطان العقبة، اسمع عدو الله، أما والله لأَفْرُغَنّ لك\nيعني اصبر عليّ بس أما أفضالك\nفتوجه للوفد المسلم وقال لهم : \nارجعوا للخِيم بتاعتكم، قبل ما أحد من المشركين ييجي\nالمفروض دلوقتي إن الوفد المسلم يروح بسرعة قبل ما المشركين ييجوا،\nلكن الوضع كان مختلف\nقام واحد من الوفد اسمه العباس بن عبادة وقال لرسول الله ﷺ :\nوالله يا رسول الله لو عايز نحارب أهل مِنَى كلهم دلوقتي \nخدوا بالكم إن الإتفاق كان إن المسلمين في يثرب ينصروا رسول الله ﷺ  ويدافعوا عنه ويجاهدوا معاه لما يروح عندهم يثرب،\nفهم دلوقتي بيعطوا رسول الله ﷺ أكثر من البيعة ومن إللي اتفقوا عليه، لأن إللي عايز الجنة بيبذل أي حاجة مهما كانت عشان يوصل لها،\nيعني كأنهم بيقولوا بالدليل العملي يارسول الله ده أول إثبات  مننا على صدق بيعتنا \nلكن رسول الله ﷺ  قال لهم : أنا لم أؤمر بكده، يعني مجاليش الأمر من ربنا إني أقاتل أهل الحج\nأيوة إنتم بايعتم وكل حاجة لكن مش ده وقت التطبيق \nوالحكمة فعلا إن ميكونش أي مواجهة دلوقتي بين الوفد وبين أهل مكة،\nلأنهم هيُبادوا كلهم\nحلو أوي إنهم يموتوا كلهم شهداء، لكن فين الدولة إللي احنا عمالين نخطط لبنائها، فين بناء الأمة الإسلامية إللي هتنشر الدين في كل الدنيا\nيبقى الصح إننا ننسحب دلوقتي ونتجنب المواجهة ، لحد ما نبقى أقوى وييجي الوقت المناسب للمواجهة \nسمع الوفد الإسلامي كلام رسول الله ﷺ ورجعوا للخيام بتاعتهم وباتوا مع باقي الوفد المشرك إللي هم أتوا معاهم،\nتاني يوم جاء كفار مكة لرئيس وفد الحج إللي جاء من يثرب وكان مشرك واسمه :《عبد الله بن أُبَيّ بن سَلُول》\n☆ من أكثر الشخصيات إللي بكرهها جدا \nخليكم فاكرين اسمه عشان هيكون له دور في أحداث رهيبة هتحصل بعدين\nالمهم قعدوا معاه وقالوا له بأسلوب في ترغيب وترهيب:\nيا معشر الخزرج !\nاحنا وصل لنا إنكم قعدتم مع صاحبنا ده، عشان عايزين تطلعوه برة مكة وتبايعوه على حربنا\nوأنتم أكثر ناس منحبش إن يكون في بينا وبينهم حرب، \nلكن لو استمريتم على الوضع ده هنحاربكم، وإنتم عارفين كويس أوي مين هي قريش\nفعبد الله بن أبي بن سلول قال لهم بكل انفعال:\nالكلام ده مش صحيح، عمر ما حاجة زي كده تحصل من غير ما يستشيروني، ده أنا حتى لو في يثرب مش هياخدوا قرار زي ده إلا لما يسألوني\nهو فعلا صادق لأنه ميعرفش إللي حصل بين الوفد المسلم وبين رسول الله ﷺ،  وهو بيتكلم بكل ثقة لأن الأوس والخزرج كانوا شبه متفقين إن إللي هيحكم يثرب عبد الله بن أبي سلول، \nلأن يثرب مكنش لها رئيس، لكنهم اتفقوا على الرجل ده بس لسه الموضوع مش رسمي،\nفهو عمال يدافع والمسلمين قاعدين ساكتين يبصوا لبعض ولا كأنهم عملوا حاجة\nالمشركين من أهل مكة اقتنعوا بكلام عبد الله بن أبي بن سلول ومشيوا، وبعدها كانوا لموا حاجتهم وخلاص مشيوا راجعين ليثرب،\nلما كفار قريش رجعوا داخل مكة، عرفوا إن فعلا حصل لقاء بين الوفد من أهل يثرب وبين رسول الله ﷺ،  عرفوا منين وإزاي،\nممكن من صوت الشيطان إللي سمعوه أو حد شاف الوفد وهم بيتسللوا،\nالمهم إنهم عرفوا وخلاص، فراحوا راجعين للوفد تاني لقوهم مشيوا لأنه كان آخر يوم في الحج، \nودي حاجة رسول الله ﷺ  كان عامل حسابه فيها\nحاولوا يلحقوهم وطاردوهم فعلا لحد ما لحقوا اثنين المنذر بن عمرو وسعد بن عبادة وكانا مسلمين، وكمان من النقباء الاثنا عشر\nالمنذر بن عمرو قدر يهرب، سعد بن عبادة معرفش، راحوا ماسكينه ومكتفينه ورجعوا بيه لمكة وقعدوا يعذبوه ويضربوه، ويعتبر سعد بن عبادة هو الوحيد إللي اتعذب داخل مكة زي المسلمين إللي كانوا في مكة،\nالمهم قعدوا يضربوا فيه ويعذبوه لحد ما واحد من الناس سأله: إنت يابني ملكش حد هنا في قريش تعرفه يقدر يحميك \n فقال له سعد من تحت الضرب : في...جُبَير بن مُطعم والحارث بن حرب كنت بساعدهم وأحميهم لما يخرجوا في تجارة ويعدوا علينا في يثرب\nفالرجل راح بسرعة يبحث عن جبير بن مطعم والحارث بن حرب لقاهم عند الكعبة، فقال لهم :\nإلحقوا في واحد بينضرب وبيقول إنه يعرفكم \nفقالوا: اسمه إيه، قال لهم : سعد بن عبادة\nقالوا : صح احنا فعلا نعرفه \nوراحوا فعلا وخلصوه من المشركين\nاستطاع سعد بن عبادة إنه يلحق بالقافلة ورجع مع الوفد ليثرب، وبدأ التجهيز لاستقبال رسول الله ﷺ والمسلمين إللي هيهاجروا من مكة ليثرب\nاحنا دلوقتي في آخر السنة الثالثة عشر للبعثة، الأوضاع في يثرب مستقرة إلى حد كبير،\nالأوضاع في مكة كلها قلق، هم عارفين إن في حاجة بتدبر في الخفاء، لكن إيه هي بالتحديد مش عارفين\nفي وسط الأوضاع دي جاء الأمر الإلهي للمسلمين في مكة بالهجرة ليثرب\nكل مسلم قادر يجب عليه الهجرة فورا، الموضوع دلوقتي مش اختياري، ده أمر مباشر بالهجرة، الرجال والنساء، القوي والضعيف الغني والفقير الحر والعبد...الكل لازم يهاجر\nالموضوع صعب \nالهجرة معناها إنهم هيسيبوا أموالهم وبيوتهم وذكرياتهم وأهلهم...معناها إنهم هيستعدوا لتكاليف أصعب ، هيحاربوا ويعادوا كل الأرض\nأمر رسول الله ﷺ الناس بالهجرة وهو لم يهاجر، مستني لما يطمن إن كل واحد يقدر يهاجر خلاص طلع من مكة،\nوهو كده بيعلمنا إن القيادة والزعامة مسؤولية وأمانة، مش ترف ورفاهية وإن الزعيم يضحي برعيته عشان يحمي نفسه ومنصبه\nبدأ المسلمون بالهجرة وكان أول من هاجر من المسلمين إلى يثرب هو أبو سلمة عبد الله بن عبد الأسد المخزومي وهو ابن عمة رسول الله ﷺ، \nبعدما قرر أبو سلمة إنه يخرج وجهز نفسه وزوجته ومعاهم ابنهم سلمة وركبهم على البعير ومسك حبل البعير بيقوده،\nشافه ناس من أقارب زوجته أم سلمة،\nقالوا له: شوف.. إنت حر في نفسك لكن متاخدش بنتنا تلف بيها وتبهدلها معاك\nوراحوا شادين حبل البعير وأخذوا أم سلمة إللي قاعدة على البعير وابنها في حجرها،\nراح أهل أبو سلمة غضبوا، إزاي يأخذوا منه زوجته، راحوا قايلين : \nطب والله ماحنا سايبين ابننا عندها، هاتوا الواد\nودول ماسكين الطفل الصغير يشدوه والتانيين يشدوا لحد ما الولد إيده اتخلعت \nوأخذه أهل زوجها، وحبسها أهلها وانطلق أبو سلمة ناحية يثرب مهاجر واتفرق بينها وبين زوجها وابنها\nوقعدت سنة كاملة تخرج كل يوم الصبح تقعد على الطريق تبكي لحد المساء،\nفعدى عليها واحد من أبناء أعمامها وشافها فصعبت عليه، فراح مكلم أهلها وقال لهم : متسيبوا المسكينة دي فرقتم بينها وبين زوجها وابنها\nفقالوا لها:\nروحي لزوجك لو إنتي عايزة\nفساعتها أهل أبو سلمة رجعوا لها ابنها، فأخذت ابنها وركبت على الراحلة وسافرت ليثرب عشان تروح لزوجها لوحدها،\n☆أنا دايما كنت بستغرب من القصة دي، إزاي أبو سلمة قدر يسيب زوجته وابنه إللي ذراعه انخلع ويمشي يهاجر كده عادي\nلا والأعجب إن زوجته أم سلمة كانت تقول ومين خير من أبي سلمة\nده لو في زماننا كان زمان الدنيا قامت مقعدتش\nكان زمان الزوجة قعدت تقول بقى الراجل هنت عليه يسيبني ويسيب ابنه ويمشي كده ولا كأننا متجوزين وفي بينا عِشرة\nولا كان زمانها ضغطت عليه إنه عادي يعني مش لازم تسيبنا، خليك معانا لحد ما الدنيا تتظبط وبعدين نسافر مع بعض\nبس واضح إن الناس دي كان عندهم الدين وأوامر الله ورسوله حاجة غالية أوي \nمهما طال الإبتلاء ربنا هيرفعه في يوم من الأيام، فسبحان من سخر لأم سَلَمة ابن عمها عشان يكلم أهلها وسبحان من غير قلوب أهلها وخلاهم يوافقوا إنها تروح لزوجها\nهنشوف تضحيات كثيرة في الهجرة، في إللي ضحّى بماله، وإللي ضحّى ببيته، يعني كانت العائلة كلها تخرج وتسيب بيوتها في مكة،\nوخدوا بالكم مفيش رجعة مرة أخرى للبيوت دي...يعني مجرد ما يطلعوا من مكة ويهاجروا خلاص \nتتابع المسلمون في الهجرة ليثرب وكان بيستقبلهم المسلمون في يثرب عشان ينصروهم ويساعدوهم،\nفبقى المسلمين إللي بيهاجروا من مكة اسمهم: 《المهاجرين》\nوالمسلمين إللي في يثرب بيستقبلوا المهاجرين وإللي بايعوا رسول الله ﷺ بيعة العقبة الثانية بقى اسمهم :\n《الأنْصَار》\n☆والأنصار غير النصارى \nالأنصار هم المسلمين إللي نصروا وآوَوْا المهاجرين ورسول الله ﷺ \nأما النصارى فهم إللي بيتبعوا دين النصرانية، الدين إللي اتحرف من بعد عيسى عليه السلام\nوكان المسلمون بيهاجروا في السر، لأن لو قريش عرفت عن أحد إنه مهاجر كانت بتمنعه، أو حتى تحاول قتله\nواحنا قلنا قبل كده ليه قريش رافضة إن المسلمين يهاجروا أصلا لما اتكلمنا عن هجرة الحبشة فمش هعيد الكلام تاني \nرسول الله ﷺ فضل مستني شهرين بعد بيعة العقبة الثانية لحد ما كل المسلمين إللي يقدروا يخرجوا من مكة خرجوا وهاجروا ليثرب،\nاحنا دلوقتي في شهر صفر من السنة الرابعة عشرة من البعثة ،\nاتبقى في مكة ثلاثة فقط من إللي يقدروا يهاجروا وهم :\nأبو بكر الصديق وأهل بيته وعلي بن أبي طالب ورسول الله ﷺ،\nوسبب وجود أبو بكر وعلي في مكة لحد دلوقتي كان بأمر من رسول الله ﷺ لأن كل واحد فيهم له دور هيؤديه بعدين زي ما هنشوف إن شاء الله \nطبعا كلكم مستنيين أحكي قصة هجرة عمر بن الخطاب وإزاي إن هو الوحيد إللي هاجر علانية وراح لأهل مكة وقال لهم: من أراد أن تَثْكله أمه أو يُيَتم ولده فليتبعني خلف هذا الوادي فإني مهاجر \n◇لكن للأسف القصة طلعت ضعيفة لا تصح عن عمر بن الخطاب\nالقصة الصحيحة إنه اتفق مع ثلاثة من أصحابه المسلمين إنهم يتقابلوا في مكان برة مكة وقالوا :\nأي واحد فينا ميجيش المكان ده الباقي هيعرف إنه اتحبس ومقدرش ييجي، فالباقي يمشي ويهاجروا\nوفعلا جاء عمر بن الخطاب للمكان وجاء صاحب له والثالث مجاش، فهاجر عمر وصاحبه وهم في الطريق قابلوا عشرين واحد من الصحابة فدخلوا يثرب مع بعض،\nوكان سابقهم مصعب بن عمير ومعاه عبد الله بن أم مكتوم الأعمى \nوجاء بعدهما عمار بن ياسر، وبلال بن رباح وسعد بن أبي وقاص رضي الله عنهم أجمعين\nمصدر كلامي كتاب:\n《ما شاع ولم يثبت في السيرة النبوية》\n☆ممكن حد يسأل طيب هو ليه الشيوخ بتحكي الروايات الضعيفة \n لأن السّيَر لا تُعامل معاملة الأحاديث الصحيحة، يعني بيذكروها من باب الاستئناس مادام مش بيتبنى عليه أحكام شرعية وده جائز وكان السلف بيعملوا كده،\nلكن أنا في السلسة دي ببعد عن أي حديث في ضعف وبنقل القصة الصحيحة فقط \nإزاي رسول الله ﷺ هاجر وإيه الخطة إللي حطها عشان يقدر يهاجر بسلام،\nده إللي هنعرفه الجزء إللي بعد الجاي تقريبا، لأن الجزء الجاي هنتكلم عن.....\nهنتكلم عن إيه\nتابعوا معانا وإن شاء الله هتعرفوا \n☆"}, {"n": 71, "l": "الجزء 45 | قصص القرآن | لقمان | أصحاب الجنه", "u": "https://www.facebook.com/groups/710210019782034/permalink/786110975525271/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والأربعون\n#قصص_القرآن\n#أصحاب_الجنة\n#لقمان\nوقفنا المرة إللي عند رسول الله ﷺ وهو بيجهز لهجرته ليثرب،\nلكن قبل ما نسيب مكة مع رسول الله ﷺ  ونهاجر ليثرب محتاجين نعرف قصتين من قصص القرآن نزلت في مكة خلال الثلاثة عشرة سنة إللي عاشاها رسول الله ﷺ بعد البعثة\n◇القصة الأولى قصة أصحاب الجنة،\nربنا أنزل آيات في سورة القلم في بداية الدعوة بيحكي لرسول الله وللمسلمين ولكفار قريش قصة رجل صالح من أهل الكتاب وأبنائه الخمسة في الزمن إللي فات،\nعشان يضرب لهم المثل ويقول لهم عاقبة إللي بيكفر نعمة ربنا هتكون إيه\nكان في رجل صالح عنده جنة، يعني حديقة كبيرة جدا مليانة أنواع الشجر والنخيل والثمار ،يُقال إن الجنة دي كان في مدينة من مدن اليمن، \nالرجل الصالح ده كان من عادته إنه يقسم الثمار أو المحصول ثلاثة أقسام، قسم بياخده لبيته وأولاده،\nوقسم بيوزعه على الفقراء والمساكين، وقسم بيرجعه الأرض تاني عشان يعيد إنتاجه،\nوكان ربنا مُبارِك له بسبب صدقته على الفقراء والمساكين، \nعياله مكنش عاجبهم الموضوع، بالنسبة لهم أبوهم ده رجل بيضيع فلوسه وإنهم أوْلى بالثمار إللي أبوهم بيوزعها عالناس دي، \nالمفروض يُؤَمن مستقبلنا احنا، حد عارف المستقبل فيه إيه\nماعدا واحد فيهم كان شايف إن إللي أبوه بيعمله هو الصح، وإن الرزق والنعم إللي هم فيها دي بسبب بركة ربنا لهم في البستان بتاعهم،\nعدت السنين ومرض أبوهم ومات وورث الأبناء الخمسة البستان، وكان في السنة إللي أبوهم مات فيها دي محصول البستان بتاعهم كثير جدا أكثر من أي سنة فطمعوا \nو قالوا: \nأبونا ده كان رجل أحمق ، يعني مش بيعرف يدبر أموره،\nبيصرف على الفقراء من أموالنا دي\nفاحنا بقى مش هنعطي لأي أحد حاجة من الثمار دي وهنوفر ونعيش مرتاحين\nفأخوهم الأوسط قال لهم:\n بلاش تعملوا كده، خليكم زي ما كان أبونا بيعمل، الثمر إللي إنتم شايفينه ده بسبب بركة ربنا\nطبعا مسمعوش الكلام\nاتفقوا مع بعض وأقسموا من غير ما يقولوا إن شاء الله ،\nإنهم هيصحوا الصبح بدري في أواخر الليل كده عشان يجمعوا الثمار  قبل ما أي أحد من الفقراء والمساكين ييجي ومش هيستثنوا ولا واحد من الناس دي\n\"إِنَّا بَلَوْنَاهُمْ كَمَا بَلَوْنَا أَصْحَابَ الْجَنَّةِ إِذْ أَقْسَمُوا لَيَصْرِمُنَّهَا مُصْبِحِينَ\"\n ده كان تدبيرهم وتخطيطهم، لكن رب العالمين يعلم بكل شيء، فأرسل على البستان بتاعهم عذاب من السماء، يقال إن العذاب ده كان نار أحرقت كل البستان لحد ما بقى أسود فحمة وكل ده وهم نايمين ميعرفوش حاجة\n\"فَطَافَ عَلَيْهَا طَائِفٌ مِنْ رَبِّكَ وَهُمْ نَائِمُونَ* فَأَصْبَحَتْ كَالصَّرِيمِ\"\nكانوا عايزين يمعنوا حق ربنا في الفقراء والمساكين عشان يحوّشوا ويزودوا دخلهم ونسيوا إن ربنا هو إللي بيرزق،\nوإن الثمار دي لولا إن ربنا أذن إنها تخرج مكنتش خرجت،\nفعاقبهم الله بعكس إللي كانوا بيخططوا له،\nيعني مش بس مفيش حاجة تحوشوها، لأ...ده حتى الجزء إللي كنتم بتاخدوه كل سنة مش هتاخدوا منه ثمرة \n\"وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ \"\nصحيوا الصبح ...يلا يا جماعة بسرعة نروح قبل ما أحد ييجي لو إنتم فعلا جادين في كلامكم بتاع امبارح\n\"  فَتَنَادَوْا مُصْبِحِينَ * أَنِ اغْدُوا عَلَى حَرْثِكُمْ إِنْ كُنْتُمْ صَارِمِينَ\"\nمشيوا براحة ومن غير ما يعملوا أي صوت عشان محدش يحس بيهم من الفقراء وييجي يطلب منهم الصدقة\n\"فَانْطَلَقُوا وَهُمْ يَتَخَافَتُونَ * أَنْ لَا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِسْكِينٌ * وَغَدَوْا عَلَى حَرْدٍ قَادِرِينَ\"\nأول ما وصلوا البستان لقوها عبارة عن سواد كل حاجة محروقة \nقالوا إيه ده...احنا تهنا ولا إيه\n\"فَلَمَّا رَأَوْهَا قَالُوا إِنَّا لَضَالُّونَ\"\nفلما اتأكدوا إن إن فعلا ده البستان بتاعهم عرفوا إن ربنا غضب عليهم وعاقبهم بسبب نيتهم الخبيثة بمنع حق الفقراء،\n\"بَلْ نَحْنُ مَحْرُومُونَ\"\n☆ممكن حد يسأل سؤال ويقول طيب هم أصلا لسه معملوش الغلط، يعني المفروض ربنا يعاقبهم لما يحصل منهم الخطأ مش قبلها،\n لأن إللي بينوي عمل سيئة ومعملهاش ربنا مش بيكتبها عليه، فليه بقى ربنا عاقبهم على ذنب لسه محصلش\nلما تكون نية عمل السيئة مجرد خاطرة جت على بال الإنسان، أو إنه هيعملها بس تذكر ربنا فخاف ورجع عنها،\n هنا ربنا لا يعاقبه ولا تُكتب له سيئة\nلكن الإنسان إللي مخطط ومصمم وعاقد النية ومرتب أموره إنه يعمل المعصية تكتب له سيئة وربنا يعاقبه عليه حتى قبل ما ينفذها،\nيعني باختصار يأثم الإنسان إذا وصل لمرحلة العزم والتصميم حتى لو مكنش لسه عمل المعصية\nهنا تكلم أخوهم الأوسط وكان قد خرج معهم لعله يقول لهم كلمة تنفعهم ويرجعوا عن إللي في دماغهم، قال لهم:\nمش أنا حذرتكم ومسمعتوش كلامي\n\"قَالَ أَوْسَطُهُمْ أَلَمْ أَقُلْ لَكُمْ لَوْلَا تُسَبِّحُونَ\"\nقالوا : فعلا كان معاك حق احنا ظلمنا نفسنا، ومكنش ينفع نمنع الفقراء والمساكين\n\"قَالُوا سُبْحَانَ رَبِّنَا إِنَّا كُنَّا ظَالِمِينَ\"\nفقعدوا يرموا اللوم على بعض...كل واحد بقى يقول إنت السبب إنت إللي شجعتنا ،\n\"فَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَلَاوَمُونَ \"\n☆ودي عادة الناس، لما يلاقوا نفسهم وقعوا في الغلط يدوروا على أي حد يرموا عليه غلطهم\nماشية في الشقة روحتي خابطة كوباية مية برجلك، أول حاجة بتقوليها مين إللي حط الكوباية هنا\nمبتفكريش مثلا إنك إنتي إللي غلطانة عشان ماشية مش واخدة بالك، وهتلاقي بتطلعي نفسك مائة مبرر\nأنا في دماغي كذا حاجة ..أنا هاخد بالي من إيه ولا إيه وهكذا\nفهم قعدوا يلوموا بعض وإن كل واحد فيهم هو السبب في إللي حصل،\nوبعدين قالوا فعلا احنا اعتدينا وطغينا وتعدينا حدود ربنا واحنا معترفين بغلطنا،\n\"قَالُوا يَا وَيْلَنَا إِنَّا كُنَّا طَاغِينَ\"\nلكن الإعتراف بالغلط والتوبة لا يرفع العذاب إللي نزل، فعشان كده قالوا :\nلعل ربنا يرزقنا أحسن منها في الجنة بسبب توبتنا دي واحنا عايزين العفو من ربنا\n\" عَسَى رَبُّنَا أَنْ يُبْدِلَنَا خَيْرا مِنْهَا إِنَّا إِلَى رَبِّنَا رَاغِبُونَ\"\nفهم لما نزل بهم البلاء تابوا ورجعوا لربنا وهو ده المطلوب\nربنا بيقول لنا لما تحصل لواحد فيكم مصيبة راجع نفسك، راجع نيتك راجع أخطائك وتب واستغفر زي ما أصحاب الجنة عملوا\n☆طيب احنا كده فهمنا القصة ..إيه بقى علاقتها بكفار  قريش\nرسول الله ﷺ قعد يدعوا المشركين لعبادة الله، وأهل مكة ربنا أنعم عليهم بالنعم الكثيرة، رحلتي الشتاء والصيف،\nوعندهم زمزم، وعندهم الحرم الآمن،\nوعندهم الأموال بالأولاد، نعم لا تُعد ولا تُحصى فربنا أعطاهم النعم دي مش عشان هو بيحبهم ولا راضي عنهم \n هو أعطاها لهم ابتلاء واختبار زي ما ضاعف الثمار لأصحاب الجنة،\n لكنهم مع النعم دي كلها كفروا بالله ومش عايزين يسمعوا كلام رسوله، فابتلاهم الله بقحط وجدب،\nلدرجة إنهم أكلوا الجلود والجِيَف، ومع ذلك لم يؤمنوا برسول الله ﷺ ومراجعوش نفسهم زي ما أصحاب الجنة عملوا\nوإللي انتم مش قادرين تستحملوه ده ،عذاب الدنيا بس أما عذاب الآخرة فهو أكبر بكثير\n\" * كَذَلِكَ الْعَذَابُ وَلَعَذَابُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ\"\n◇القصة الثانية معانا النهاردة هي قصة لقمان الحكيم\nربنا سمى سورة كاملة باسم لقمان، وده بيدل على مكانة لقمان الحكيم،\n\"وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ\"\nالغرض من القصة إننا ناخد منها العبرة زي ما قلنا قبل كده،\nلأن القرآن مش كتاب تاريخ عشان يشرح القصص بالتفصيل\nيقول ابن كثير في البداية والنهاية إن لقمان اختلفت فيه الأقوال، يعني علماء قالوا إنه كان قاضي في زمن داوود عليه السلام، \nوعلماء قالوا إنه كان من أهل النوبة وعلماء قالوا إنه كان عبد حبشي بيشتغل نجار وكان قصير وأنفه أفطس\nوشفايفه كبيرة وغليظة وقدماه مشققة،\nنحس كده لما نسمع الوصف ده إن ده شخص الناس متبصلوش أصلا أو تبصله نظرة دونية\nولكن على الرغم من شكله ده إلا إن ربنا أعطاه الحكمة ، وبقى أحسن من ناس كثيرة لدرجة إن ربنا خلّد ذكره وقصته في القرآن، فهو حكيم من الحكماء لكنه مش نبي \n☆ودي رسالة للناس إللي أهم حاجة عندها إن شكلها يبقى شيك قصاد الناس، ربنا لا ينظر لصور الناس ولا شكلهم ولكن ينظر إلى قلوبهم،\nالناس بقت مركزة على المظاهر وإن شكلها يبقى حلو ومهتمة بنظرة الناس لها، ونسيت الباطن وإصلاح قلوبها إللي ربنا هيحاسبهم عليه\nربنا بيحكي عن لقمان وإزاي كان بينصح ابنه، وبيقول لنا القواعد الأساسية في حياة الإنسان قال له:\n♡القاعدة الأولى:\nيابني لا تُشرك بالله، يعني لا تعبد مع الله إله تاني، متدعيش حد غير ربنا،\nمتطلبش الحماية إلا من ربنا، مفيش حاجة اسمها خرزة زرقاء بتحمي، مفيش خمسة وخميسة ، مفيش حاجة اسمها إنسان ولا شجر ولاحجر نقعد نتبرك بهم، \nمتقعدش تتوسل بقبور الأنبياء والصالحين، الناس دي ماتت خلاص مش هتنفع البشر بشيء، توسل لربنا وادعيه على طول من غير واسطة\nمفيش يابني حد يعرف الغيب غير ربنا، لا عرّافين ولا مُنجّمين ولا غيرهم\nاوعي يابني تشرك بالله لأن الشرك هو الذنب الوحيد إللي ربنا لا يغفره لو الإنسان مات عليه\n\"وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ \"\n♡القاعدة الثانية:\nربنا لا يظلم مثقال ذرة ويعلم كل أمر خفي\nحتى لو صخرة إنت رميتها في البحر وجوة الصخرة دي حبة خردل ربنا عالم بيها،\nفمهما حاولت تُخفي عن ربنا شيء هو بيعلمه، ده يعلم إللي نفسك بتقوله لك من غير ما تتكلم\n\"يَا بُنَيَّ إِنَّهَا إِنْ تَكُ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ فَتَكُنْ فِي صَخْرَةٍ أَوْ فِي السَّمَوَاتِ أَوْ فِي الْأَرْضِ يَأْتِ بِهَا اللَّهُ إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ\"\n♡القاعدة الثالثة:\nالصلاة...يابني أقم الصلاة، الصلاة هي الرابط إللي بين الإنسان وبين ربه، واحنا عن اتكلمنا عن الصلاة لما كنا بنتكلم عن فرضها في رحلة الإسراء والمعراج\n\"يَابُنَيَّ أَقِمِ الصَّلَاةَ\"\n♡القاعدة الرابعة :\nالأمر بالمعروف والنهي عن المنكر\nمن أكثر الحاجات إللي اتكررت معانا كانت الأمر بالمعروف والنهي عن المنكر \nقال له :\nيا بني أؤمر الناس بالمعروف وانهاهم عن المنكر على قدر استطاعتك لو تقدر بالإيد أو اللسان أو القلب،\nوإللي بيؤمر بالمعروف وينهى عن المنكر لازم هيصيبه أذى، فلازم تصبر على الأذى إللي هيصيبك ده،\nومش عشان أصابك أذى يبقى ده مبرر ليك إنك تسيب الأمر بالمعروف والنهي عن المنكر\n\"وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ\"\n♡القاعدة الخامسة: الأخلاق\nقال له : يابني لا تتكبر على الناس، ميبقاش حد بيكلمك  ولا إنت بتكلم حد وتميل خدك كده وتبص له بجنب احتقارا له\nولما تمشي في الشارع امشي مشية متوسطة لا سريع ولا بطيء ومتمشيش تتمختر وشايف نفسك،\nمفيش أي حاجة تدعو إنك تمشي فرحان بنفسك، يوم من الأيام هتبقى في باطن الأرض إللي إنت ماشي بتكبر عليها دي\n\"وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِي الْأَرْضِ مَرَحا إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ \"\n☆وبما إننا بنتكلم عن أداب الطريق وإن الإنسان يمشي بتواضع وميكنش عنده كِبر عندنا نقطتين مهمين محتاجين نعرفهم \n◇أولا عن آداب الطريق:\nلما النساء تيجي تمشي في الشارع مينفعش يمشوا في نص الطريق، وخصوصا البنات إللي بتقعد تتصور في الشارع وتعمل حركات وهي بتتصور ويعملوا جلسات تصوير \n《فوتو سيشن》 وسط الشارع وحواليهم رجال، \nكل ده لا يجوز يا جماعة،\n المرأة ربنا أذن لها في الخروج لضرورة، ولما تخرج لها أداب لازم تلتزمها،\nرسول الله ﷺ  وهو خارج من المسجد مرة وكانت النساء بتصلي معاه فاختلط الرجال بالنساء،\n فقال للنساء استأخرن  يعني ارجعوا ورا لأن مش من حقكن إنكن تمشين في وسط الطريق، عليكن بحافات الطريق يعني أطراف الطريق بعيد عن زحمة الرجال،\nفكانت المرأة تمشي جنب الحيط لدرجة إن هدومها بتلزق في الجدار وهي ماشية تخيلوا\nمفيش واحدة فيهم قالت : \nهو في إيه يا رسول الله ...اشمعنى احنا يعني\nمتقول للرجال هم كمان ياخدوا جنب، اشمعنى هم يمشوا براحتهم عادي زي ما هم عايزين واحنا إللي نمشي جنب الحيط وهدومنا تلزق في الجدار وتتقطع يعني\nودول كانوا نساء خارجين من المسجد فاضطروا إنهم يختلطوا بالرجال ، \nمش بنات واقفين في الشارع ولا في الأوتوبيس عمالين يتصوروا ويعملوا حركات وسادين الطريق والرجالة عمالة تبص عليهم والمصيبة الأكبر إنهم أوقات كثيرة بيكونوا منتقبات،\nوتقولك النقاب مش عائق \nيا رااااجل\nرسول الله ﷺ لو كان عايش بيننا دلوقتي كان زمانه شاف وسمع العَجب\nأه خليني أقول نص الحديث عشان حبايبنا إللي ممكن يعترضوا على الكلام\n\"عن أبي أسيد الأنصاري رضي الله عنه أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ - وَهُوَ خَارِجٌ مِنْ الْمَسْجِدِ فَاخْتَلَطَ الرِّجَالُ مَعَ النِّسَاءِ فِي الطَّرِيقِ -\n فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلنِّسَاءِ : \n( اسْتَأْخِرْنَ ، فَإِنَّهُ لَيْسَ لَكُنَّ أَنْ تَحْقُقْنَ الطَّرِيقَ ، عَلَيْكُنَّ بِحَافَّاتِ الطَّرِيقِ ) \nفَكَانَتْ الْمَرْأَةُ تَلْتَصِقُ بِالْجِدَارِ حَتَّى إِنَّ ثَوْبَهَا لَيَتَعَلَّقُ بِالْجِدَارِ مِنْ لُصُوقِهَا بِهِ .\"\n◇النقطة الثانية وهي عن الكِبر والخُيَلاء\nحديث رسول الله ﷺ من جر ثوبه خيلاء لم ينظر الله إليه، فالسيدة أم سلمة بتقول له طيب يارسول الله والنساء تعمل إيه في ذيولها لأن طبيعة لبس المرأة بيكون طويل عشان مفيش حاجة منها تبان، فقال لها خلاص النساء تطول مقدار شبر بعد الكعب ،\nفأم سلمة قالت : بس كده يا رسول الله رجلهم هتنكشف وهم ماشيين\nفقال لها : خلاص يطولوا لبسهم بمقدار ذراع من بعد الكعب وميزيدوش على كده \n\"مَنْ جَرَّ ثَوْبَهُ خُيَلَاءَ لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ، فَقَالَتْ أُمُّ سَلَمَةَ: فَكَيْفَ يَصْنَعْنَ النِّسَاءُ بِذُيُولِهِنَّ؟\n قَالَ: يُرْخِينَ شِبْرًا فَقَالَتْ: إِذًا تَنْكَشِفُ أَقْدَامُهُنَّ. قَالَ: فَيُرْخِينَهُ ذِرَاعًا لَا يَزِدْنَ عَلَيْهِ. \"\nالحديث ده بيطلع منه حكم إن فستاين الأفراح إللي لها ذيل طويل ده لا تجوز\nلأن رسول الله ﷺ قال كده بكل صراحة يطولوا ذراع وميزدوش\nوالذراع طوله حوالي ستة وأربعون سنتيمتر، يعني تحسبوا من بعد عظمة الكعب ستة وأربعين سنتيمتر،\n ده أقصى طول ممكن المرأة تطول به ثوبها عشان الستر فقط، وإن رجلها متبنش\nأكثر من كده هتدخل في الحديث\nوخدوا التقيلة\nإن المرأة لو صلت في ثوب طوله أكثر من ذراع من تحت الكعب وهي عارفة النهي ده فصلاتها باطلة\nشوفوا احنا عمالين نتكلم في ستر أقدام مش ستر جسم بنات لابسين بناطيل مقطعة وهدوم ضيقة مفصلة أجسامهن  ولا ستر وجه\nورسول الله ﷺ مأنكرش على أم سلمة وهي بتقول له يارسول النساء رجلها تتكشف\nيعني مقلهاش وإيه يعني رجلها تتكشف هو الراجل هيسيب كل حاجة فيها ويبص على رجلها،\nبلاش تنطع وتشدد يا أم سلمة الدين يسر \nمش بقولكم لو رسول الله ﷺ كان معانا كان زمانه شاف وسمع العجب\nومن الأخلاق إللي نصح لقمان ابنه بها إنه يوطي صوته لما ييجي يتكلم لأن أعلى صوت وأنكرها والناس بتكرهه هو صوت الحمير ،\nفمادام هو مش محتاج إنه يعلي صوته ومفيش مناسبة لتعلية الصوت زي رفع الأذان مثلا يبقى يحافظ على توطية صوته\nطبعا البنات إللي صوتها عالي هتزعل دلوقتي \nشوفوا...حاولوا بقدر الإمكان إنكم متضحكوش بصوت عالي في الشارع ولا تتكلموا بصوت عالي،\nولو حصل منكم سهوا وبدون قصد إن صوتكم عِلي فإن شاء الله ربنا يتجاوز عنها،\nلأن صوت المرأة في الأصل مش عورة إلا لو اتكلمت بطريقة فيها دلع أو ميوعة، أو صوتها نفسه فتنة،\nغير كده فمباح إن المرأة تتكلم عادي"}]);
